window.TOEIC_VISUAL_STORY_TRANSCRIPTS = {"t1-32":{"conversationId":"t1-32","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[8,9]},"timebase":"source-seconds","timingMethod":"Measured automatic word anchors from the original MP3; scene-switch times still require editorial approval.","utterances":[{"id":"t1-32-u01","speaker":"W","text":"Hey, Oliver. Did you see the focus group results for our new spicy cheddar cheese?","start":6.03,"end":11.52,"clipSrc":"../../audio-sentences/t1-32-meaning-01.mp3","clipSourceStart":5.95},{"id":"t1-32-u02","speaker":"W","text":"Everyone really liked it.","start":12.09,"end":13.71,"clipSrc":"../../audio-sentences/t1-32-meaning-02.mp3","clipSourceStart":12.01},{"id":"t1-32-u03","speaker":"M","text":"Yes. It should be a great addition to our company's line of cheeses.","start":14.1,"end":18.18,"clipSrc":"../../audio-sentences/t1-32-meaning-03.mp3","clipSourceStart":14.02},{"id":"t1-32-u04","speaker":"W","text":"Several people mentioned that they'd like to use it in recipes-to add to sauces, for example.","start":18.66,"end":24.39,"clipSrc":"../../audio-sentences/t1-32-meaning-04.mp3","clipSourceStart":18.58},{"id":"t1-32-u05","speaker":"M","text":"So maybe we should consider selling a shredded version that would melt easily when cooked.","start":24.84,"end":29.61,"clipSrc":"../../audio-sentences/t1-32-meaning-05.mp3","clipSourceStart":24.76},{"id":"t1-32-u06","speaker":"W","text":"I'm sure we could do that. I'll get in touch with the production manager with that request.","start":30.15,"end":35.52,"clipSrc":"../../audio-sentences/t1-32-meaning-06.mp3","clipSourceStart":30.07}]},"t1-35":{"conversationId":"t1-35","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[9,10]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-35-u01","speaker":"M","text":"Hi. I'm calling to book three tickets for this Thursday's tennis match.","start":6.12,"end":10.44,"clipSrc":"../../audio-sentences/t1-35-meaning-01.mp3","clipSourceStart":6.04},{"id":"t1-35-u02","speaker":"M","text":"Are there any seats left?","start":10.89,"end":12.21,"clipSrc":"../../audio-sentences/t1-35-s03.mp3","clipSourceStart":10.81},{"id":"t1-35-u03","speaker":"W","text":"Just a few! Tickets for Thursday's match have been selling quickly.","start":12.63,"end":16.68,"clipSrc":"../../audio-sentences/t1-35-s04.mp3","clipSourceStart":12.55},{"id":"t1-35-u04","speaker":"M","text":"I'm not surprised! After all, Ife Rotimi won the regional championship tournament last month.","start":17.13,"end":23.43,"clipSrc":"../../audio-sentences/t1-35-s05.mp3","clipSourceStart":17.05},{"id":"t1-35-u05","speaker":"M","text":"Everyone wants to see her play after her incredible performance.","start":24.03,"end":28.05,"clipSrc":"../../audio-sentences/t1-35-s06.mp3","clipSourceStart":23.95},{"id":"t1-35-u06","speaker":"W","text":"Well, there's only one group of three seats together.","start":30.24,"end":32.91,"clipSrc":"../../audio-sentences/t1-35-s07.mp3","clipSourceStart":30.16},{"id":"t1-35-u07","speaker":"W","text":"Advance payment is required to hold them.","start":33.48,"end":35.73,"clipSrc":"../../audio-sentences/t1-35-s08.mp3","clipSourceStart":33.4}]},"t1-38":{"conversationId":"t1-38","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[10,11]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-38-u01","speaker":"W","text":"Thanks for agreeing to help me organize the library's annual fund-raising dinner, Klaus.","start":5.49,"end":9.6,"clipSrc":"../../audio-sentences/t1-38-s01.mp3","clipSourceStart":5.41},{"id":"t1-38-u02","speaker":"W","text":"We hope the event brings in enough money to expand our children's book section.","start":9.99,"end":13.86,"clipSrc":"../../audio-sentences/t1-38-s02.mp3","clipSourceStart":9.91},{"id":"t1-38-u03","speaker":"M","text":"What task would you like me to start with?","start":14.22,"end":16.17,"clipSrc":"../../audio-sentences/t1-38-s03.mp3","clipSourceStart":14.14},{"id":"t1-38-u04","speaker":"W","text":"Well, I could use some help sending out the invitations.","start":16.53,"end":19.83,"clipSrc":"../../audio-sentences/t1-38-s04.mp3","clipSourceStart":16.45},{"id":"t1-38-u05","speaker":"M","text":"OK, I can take care of that.","start":20.31,"end":21.9,"clipSrc":"../../audio-sentences/t1-38-s05.mp3","clipSourceStart":20.23},{"id":"t1-38-u06","speaker":"M","text":"Is there a list of attendees available?","start":22.393705,"end":24.39,"clipSrc":"../../audio-sentences/t1-38-s06.mp3","clipSourceStart":22.314},{"id":"t1-38-u07","speaker":"W","text":"It's in my computer files.","start":24.72,"end":26.34,"clipSrc":"../../audio-sentences/t1-38-s07.mp3","clipSourceStart":24.64},{"id":"t1-38-u08","speaker":"W","text":"I'll e-mail it to you.","start":26.82,"end":28.08,"clipSrc":"../../audio-sentences/t1-38-s08.mp3","clipSourceStart":26.74}]},"t1-41":{"conversationId":"t1-41","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[11,12]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-41-u01","speaker":"W","text":"Hey, Brian and Matteo. I found some great pens to give away at the community festival to promote our business.","start":7.17,"end":13.08,"clipSrc":"../../audio-sentences/t1-41-meaning-01.mp3","clipSourceStart":7.09},{"id":"t1-41-u02","speaker":"M1","text":"Great. Can we put our cleaning service logo on them?","start":13.41,"end":16.89,"clipSrc":"../../audio-sentences/t1-41-meaning-02.mp3","clipSourceStart":13.33},{"id":"t1-41-u03","speaker":"W","text":"Yes, for no extra charge.","start":17.31,"end":19.08,"clipSrc":"../../audio-sentences/t1-41-s05.mp3","clipSourceStart":17.23},{"id":"t1-41-u04","speaker":"W","text":"And they're biodegradable. They're made from paper.","start":19.56,"end":22.26,"clipSrc":"../../audio-sentences/t1-41-meaning-04.mp3","clipSourceStart":19.48},{"id":"t1-41-u05","speaker":"M2","text":"So when we hand them out, we can mention that.","start":22.71,"end":25.2,"clipSrc":"../../audio-sentences/t1-41-s08.mp3","clipSourceStart":22.63},{"id":"t1-41-u06","speaker":"M1","text":"As well as talk about the organic cleaning supplies our company uses.","start":25.59,"end":29.52,"clipSrc":"../../audio-sentences/t1-41-s09.mp3","clipSourceStart":25.51},{"id":"t1-41-u07","speaker":"W","text":"OK. I'll go ahead and order several cases.","start":29.91,"end":32.52,"clipSrc":"../../audio-sentences/t1-41-meaning-07.mp3","clipSourceStart":29.83}]},"t1-44":{"conversationId":"t1-44","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[13]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-44-u01","speaker":"W","text":"Jamestown Recycling Facility. How can I help you?","start":6.03,"end":9.54,"clipSrc":"../../audio-sentences/t1-44-meaning-01.mp3","clipSourceStart":5.95},{"id":"t1-44-u02","speaker":"M","text":"Hi. I'm preparing to move soon, and I have some electronics, such as televisions and computers, that I'd like to get rid of before I put my house on the market.","start":10.02,"end":19.89,"clipSrc":"../../audio-sentences/t1-44-meaning-02.mp3","clipSourceStart":9.94},{"id":"t1-44-u03","speaker":"W","text":"Yes, that's right. We'll take all electronics.","start":22.74,"end":26.04,"clipSrc":"../../audio-sentences/t1-44-meaning-03.mp3","clipSourceStart":22.66},{"id":"t1-44-u04","speaker":"M","text":"Great. I just have one question.","start":26.34,"end":28.8,"clipSrc":"../../audio-sentences/t1-44-meaning-04.mp3","clipSourceStart":26.26},{"id":"t1-44-u05","speaker":"M","text":"Do you provide a pickup service?","start":29.49,"end":31.41,"clipSrc":"../../audio-sentences/t1-44-s09.mp3","clipSourceStart":29.41},{"id":"t1-44-u06","speaker":"W","text":"No, unfortunately you'll have to bring everything here yourself.","start":31.95,"end":35.91,"clipSrc":"../../audio-sentences/t1-44-s10.mp3","clipSourceStart":31.87},{"id":"t1-44-u07","speaker":"W","text":"However, on our Web site we list a number of companies that can remove and dispose of the items for you.","start":36.48,"end":42.87,"clipSrc":"../../audio-sentences/t1-44-s11.mp3","clipSourceStart":36.4}]},"t1-47":{"conversationId":"t1-47","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[14]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-47-u01","speaker":"M","text":"Zaina! What a surprise! I haven't seen you since we took that class for business owners together last year.","start":6.09,"end":12.75,"clipSrc":"../../audio-sentences/t1-47-s01.mp3","clipSourceStart":6.01},{"id":"t1-47-u02","speaker":"W","text":"Great, thanks. I was just in the neighborhood and thought I'd stop in for a cookie or a piece of cake.","start":14.07,"end":19.98,"clipSrc":"../../audio-sentences/t1-47-meaning-02.mp3","clipSourceStart":13.99},{"id":"t1-47-u03","speaker":"W","text":"You have so many delicious baked goods here.","start":20.58,"end":23.07,"clipSrc":"../../audio-sentences/t1-47-s04.mp3","clipSourceStart":20.5},{"id":"t1-47-u04","speaker":"M","text":"Thank you! It's been a good year for business.","start":23.37,"end":25.92,"clipSrc":"../../audio-sentences/t1-47-s05.mp3","clipSourceStart":23.29},{"id":"t1-47-u05","speaker":"M","text":"I'm even considering opening a second location.","start":26.46,"end":29.16,"clipSrc":"../../audio-sentences/t1-47-s06.mp3","clipSourceStart":26.38},{"id":"t1-47-u06","speaker":"W","text":"Really? Well, I noticed that Sunnyvale Restaurant went out of business, and the building's up for lease.","start":29.4,"end":35.25,"clipSrc":"../../audio-sentences/t1-47-s07.mp3","clipSourceStart":29.32},{"id":"t1-47-u07","speaker":"W","text":"It's very close to the local university.","start":35.43,"end":37.86,"clipSrc":"../../audio-sentences/t1-47-s08.mp3","clipSourceStart":35.35}]},"t1-50":{"conversationId":"t1-50","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[15]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-50-u01","speaker":"W","text":"Hi, Koji. I think our new video game is nearly ready to be released.","start":5.85,"end":10.74,"clipSrc":"../../audio-sentences/t1-50-meaning-01.mp3","clipSourceStart":5.77},{"id":"t1-50-u02","speaker":"W","text":"Are you aware of any improvements that need to be made before then?","start":11.13,"end":14.64,"clipSrc":"../../audio-sentences/t1-50-s03.mp3","clipSourceStart":11.05},{"id":"t1-50-u03","speaker":"M","text":"Actually, I just finished testing the game this morning.","start":15.09,"end":19.08,"clipSrc":"../../audio-sentences/t1-50-s04.mp3","clipSourceStart":15.01},{"id":"t1-50-u04","speaker":"M","text":"I found a problem in the third stage of the game.","start":19.56,"end":22.5,"clipSrc":"../../audio-sentences/t1-50-s05.mp3","clipSourceStart":19.48},{"id":"t1-50-u05","speaker":"M","text":"There were a few times when my character couldn't move.","start":22.98,"end":25.68,"clipSrc":"../../audio-sentences/t1-50-s06.mp3","clipSourceStart":22.9},{"id":"t1-50-u06","speaker":"W","text":"Oh, that's strange!","start":26.64,"end":28.38,"clipSrc":"../../audio-sentences/t1-50-s07.mp3","clipSourceStart":26.56},{"id":"t1-50-u07","speaker":"M","text":"I double-checked the problem using a different controller.","start":28.71,"end":31.71,"clipSrc":"../../audio-sentences/t1-50-s08.mp3","clipSourceStart":28.63},{"id":"t1-50-u08","speaker":"M","text":"The same issue came up.","start":32.04,"end":33.75,"clipSrc":"../../audio-sentences/t1-50-s09.mp3","clipSourceStart":31.96},{"id":"t1-50-u09","speaker":"W","text":"Oh. I think Pauline had a similar problem with a game she tested.","start":34.11,"end":38.1,"clipSrc":"../../audio-sentences/t1-50-meaning-09.mp3","clipSourceStart":34.03},{"id":"t1-50-u10","speaker":"W","text":"Maybe you should ask her about it.","start":38.7,"end":40.44,"clipSrc":"../../audio-sentences/t1-50-s12.mp3","clipSourceStart":38.62}]},"t1-53":{"conversationId":"t1-53","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[16,17]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-53-u01","speaker":"M","text":"You've reached the maintenance office at Hillview Apartment Complex.","start":5.97,"end":10.23,"clipSrc":"../../audio-sentences/t1-53-s01.mp3","clipSourceStart":5.89},{"id":"t1-53-u02","speaker":"W","text":"Hi. This is Palavi Sen from unit 35B.","start":10.53,"end":14.07,"clipSrc":"../../audio-sentences/t1-53-meaning-02.mp3","clipSourceStart":10.45},{"id":"t1-53-u03","speaker":"W","text":"I'm calling because the new thermostat in my apartment isn't working.","start":14.67,"end":18.66,"clipSrc":"../../audio-sentences/t1-53-s04.mp3","clipSourceStart":14.59},{"id":"t1-53-u04","speaker":"W","text":"It keeps shutting off and turning on randomly, so my apartment is getting cold.","start":19.05,"end":23.91,"clipSrc":"../../audio-sentences/t1-53-s05.mp3","clipSourceStart":18.97},{"id":"t1-53-u05","speaker":"M","text":"When did this issue start?","start":24.33,"end":26.07,"clipSrc":"../../audio-sentences/t1-53-s06.mp3","clipSourceStart":24.25},{"id":"t1-53-u06","speaker":"W","text":"A few hours ago.","start":26.4,"end":27.54,"clipSrc":"../../audio-sentences/t1-53-s07.mp3","clipSourceStart":26.32},{"id":"t1-53-u07","speaker":"W","text":"The thermostat was just installed yesterday.","start":27.99,"end":30.54,"clipSrc":"../../audio-sentences/t1-53-s08.mp3","clipSourceStart":27.91},{"id":"t1-53-u08","speaker":"M","text":"OK. I can come and take a look at it tomorrow morning.","start":31.02,"end":34.68,"clipSrc":"../../audio-sentences/t1-53-meaning-08.mp3","clipSourceStart":30.94},{"id":"t1-53-u09","speaker":"W","text":"But it's supposed to be below freezing tonight!","start":35.07,"end":38.46,"clipSrc":"../../audio-sentences/t1-53-s11.mp3","clipSourceStart":34.99}]},"t1-56":{"conversationId":"t1-56","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[17,18]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-56-u01","speaker":"W","text":"Good morning! Welcome to Jasper Bank.","start":7.11,"end":9.6,"clipSrc":"../../audio-sentences/t1-56-s01.mp3","clipSourceStart":7.03},{"id":"t1-56-u02","speaker":"M1","text":"Thanks for meeting with us to discuss a loan for our business.","start":10.02,"end":13.08,"clipSrc":"../../audio-sentences/t1-56-s02.mp3","clipSourceStart":9.94},{"id":"t1-56-u03","speaker":"W","text":"Why don't you tell me more about your business? I understand it's a repair shop?","start":13.53,"end":18.12,"clipSrc":"../../audio-sentences/t1-56-s03.mp3","clipSourceStart":13.45},{"id":"t1-56-u04","speaker":"M2","text":"Well, ten years ago, we opened as a snowmobile repair shop, but after a few years, we also started renting out snowmobiles and other sports equipment.","start":18.48,"end":28.83,"clipSrc":"../../audio-sentences/t1-56-s04.mp3","clipSourceStart":18.4},{"id":"t1-56-u05","speaker":"M1","text":"Yes, and because winter tourism has increased recently, we'd like to expand our space so that we can carry more inventory.","start":29.19,"end":36.84,"clipSrc":"../../audio-sentences/t1-56-s05.mp3","clipSourceStart":29.11}]},"t1-59":{"conversationId":"t1-59","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[18,19]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-59-u01","speaker":"M","text":"Many of our factory workers have expressed interest in upgrading their skills.","start":6,"end":10.53,"clipSrc":"../../audio-sentences/t1-59-s01.mp3","clipSourceStart":5.92},{"id":"t1-59-u02","speaker":"M","text":"I'd like to implement a peer-training program, where learners shadow more-experienced employees and observe how they do their jobs.","start":11.13,"end":20.07,"clipSrc":"../../audio-sentences/t1-59-s02.mp3","clipSourceStart":11.05},{"id":"t1-59-u03","speaker":"W","text":"I'm afraid that might become a burden for our long-time employees.","start":20.7,"end":24.81,"clipSrc":"../../audio-sentences/t1-59-s03.mp3","clipSourceStart":20.62},{"id":"t1-59-u04","speaker":"W","text":"They'll have to slow down their work to explain what they're doing.","start":25.35,"end":28.74,"clipSrc":"../../audio-sentences/t1-59-s04.mp3","clipSourceStart":25.27},{"id":"t1-59-u05","speaker":"M","text":"What if we videotaped experienced employees doing specific tasks? High-quality video can be recorded and edited with a smartphone.","start":29.37,"end":38.73,"clipSrc":"../../audio-sentences/t1-59-s05.mp3","clipSourceStart":29.29},{"id":"t1-59-u06","speaker":"W","text":"I like that idea.","start":39.42,"end":40.68,"clipSrc":"../../audio-sentences/t1-59-s06.mp3","clipSourceStart":39.34},{"id":"t1-59-u07","speaker":"W","text":"It would allow us to capture our workers' expertise without slowing down the production line.","start":41.16,"end":46.5,"clipSrc":"../../audio-sentences/t1-59-s07.mp3","clipSourceStart":41.08}]},"t1-62":{"conversationId":"t1-62","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[19,20]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-62-u01","speaker":"W","text":"Hi, Suresh, I'm at the airport waiting for my flight.","start":6.96,"end":10.32,"clipSrc":"../../audio-sentences/t1-62-s01.mp3","clipSourceStart":6.88},{"id":"t1-62-u02","speaker":"W","text":"I want to meet with a potential investor while I'm in Chicago.","start":10.95,"end":14.52,"clipSrc":"../../audio-sentences/t1-62-s02.mp3","clipSourceStart":10.87},{"id":"t1-62-u03","speaker":"W","text":"Her name's Marta Gomez.","start":15,"end":16.68,"clipSrc":"../../audio-sentences/t1-62-s03.mp3","clipSourceStart":14.92},{"id":"t1-62-u04","speaker":"M","text":"OK. Which day would you prefer to meet with her?","start":19.83,"end":22.77,"clipSrc":"../../audio-sentences/t1-62-meaning-04.mp3","clipSourceStart":19.75},{"id":"t1-62-u05","speaker":"W","text":"How about right after my meeting with the Chicago staff?","start":23.34,"end":26.64,"clipSrc":"../../audio-sentences/t1-62-s06.mp3","clipSourceStart":23.26},{"id":"t1-62-u06","speaker":"M","text":"OK. By the way, did you see that our company won an award for our contributions to the community? It was just announced this morning.","start":27.18,"end":35.04,"clipSrc":"../../audio-sentences/t1-62-meaning-06.mp3","clipSourceStart":27.1}]},"t1-65":{"conversationId":"t1-65","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[20,21]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-65-u01","speaker":"M","text":"Marion, we keep getting calls from people who want to visit the botanical garden but can't find parking information.","start":7.53,"end":14.88,"clipSrc":"../../audio-sentences/t1-65-s01.mp3","clipSourceStart":7.45},{"id":"t1-65-u02","speaker":"M","text":"Isn't it on our Web site?","start":15.51,"end":17.19,"clipSrc":"../../audio-sentences/t1-65-s02.mp3","clipSourceStart":15.43},{"id":"t1-65-u03","speaker":"W","text":"It is, but you have to click on the \"About Us\" page and scroll to the bottom of that page.","start":17.49,"end":23.19,"clipSrc":"../../audio-sentences/t1-65-s03.mp3","clipSourceStart":17.41},{"id":"t1-65-u04","speaker":"W","text":"Maybe people don't see it.","start":23.73,"end":25.32,"clipSrc":"../../audio-sentences/t1-65-s04.mp3","clipSourceStart":23.65},{"id":"t1-65-u05","speaker":"M","text":"Oh, I think we should move that information from the \"About Us\" page and make a separate page for directions and parking information.","start":25.86,"end":33.69,"clipSrc":"../../audio-sentences/t1-65-s05.mp3","clipSourceStart":25.78},{"id":"t1-65-u06","speaker":"W","text":"I'd be happy to make that change.","start":37.26,"end":38.97,"clipSrc":"../../audio-sentences/t1-65-s06.mp3","clipSourceStart":37.18},{"id":"t1-65-u07","speaker":"W","text":"But we're in the middle of updating our software, so it'll have to wait until Monday.","start":39.24,"end":43.74,"clipSrc":"../../audio-sentences/t1-65-s07.mp3","clipSourceStart":39.16}]},"t1-68":{"conversationId":"t1-68","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript test 1 ets 2026.pdf","pages":[22,23]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t1-68-u01","speaker":"M","text":"Good news! We have finally received the go-ahead for our department's project to install bicycle racks at the train station downtown.","start":6.87,"end":15.21,"clipSrc":"../../audio-sentences/t1-68-s01.mp3","clipSourceStart":6.79},{"id":"t1-68-u02","speaker":"W","text":"At last! So, now we need to decide where to place the racks.","start":15.57,"end":20.52,"clipSrc":"../../audio-sentences/t1-68-s02.mp3","clipSourceStart":15.49},{"id":"t1-68-u03","speaker":"W","text":"How about by the station entrance?","start":21,"end":23.04,"clipSrc":"../../audio-sentences/t1-68-s03.mp3","clipSourceStart":20.92},{"id":"t1-68-u04","speaker":"M","text":"Hmm. If we asked riders, I bet they'd say that the most convenient spot is as close to the platform as possible.","start":23.76,"end":31.68,"clipSrc":"../../audio-sentences/t1-68-meaning-04.mp3","clipSourceStart":23.68},{"id":"t1-68-u05","speaker":"W","text":"Let's do that. I'll contact some companies for estimates.","start":31.98,"end":36,"clipSrc":"../../audio-sentences/t1-68-meaning-05.mp3","clipSourceStart":31.9}]},"t2-32":{"conversationId":"t2-32","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[7,8]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-32-u01","speaker":"W","text":"How were your deliveries?","start":6.03,"end":7.41,"clipSrc":"../../audio-sentences/t2-32-s01.mp3","clipSourceStart":5.95},{"id":"t2-32-u02","speaker":"M","text":"Not bad, except at that new residential building on South Street.","start":7.92,"end":12.12,"clipSrc":"../../audio-sentences/t2-32-s02.mp3","clipSourceStart":7.84},{"id":"t2-32-u03","speaker":"M","text":"I had to call them on my phone to come pick up their food.","start":12.54,"end":15.42,"clipSrc":"../../audio-sentences/t2-32-s03.mp3","clipSourceStart":12.46},{"id":"t2-32-u04","speaker":"M","text":"At first, I tried to call on the building intercom, but it's still broken.","start":15.96,"end":19.98,"clipSrc":"../../audio-sentences/t2-32-s04.mp3","clipSourceStart":15.88},{"id":"t2-32-u05","speaker":"W","text":"You're not the first to say that.","start":20.64,"end":22.29,"clipSrc":"../../audio-sentences/t2-32-s05.mp3","clipSourceStart":20.56},{"id":"t2-32-u06","speaker":"W","text":"Last week, a customer called to complain that their food was cold by the time they found it.","start":22.59,"end":27.51,"clipSrc":"../../audio-sentences/t2-32-s06.mp3","clipSourceStart":22.51},{"id":"t2-32-u07","speaker":"M","text":"Maybe we just can't make deliveries there until the landlord fixes the intercom system.","start":28.14,"end":33,"clipSrc":"../../audio-sentences/t2-32-s07.mp3","clipSourceStart":28.06},{"id":"t2-32-u08","speaker":"W","text":"I'm going to update the instructions on our mobile app telling customers to meet us at the building's front door.","start":33.6,"end":39.36,"clipSrc":"../../audio-sentences/t2-32-s08.mp3","clipSourceStart":33.52},{"id":"t2-32-u09","speaker":"W","text":"Let's see if that helps.","start":39.57,"end":40.92,"clipSrc":"../../audio-sentences/t2-32-s09.mp3","clipSourceStart":39.49}]},"t2-35":{"conversationId":"t2-35","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[8,9]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-35-u01","speaker":"W","text":"We're getting close to the time of year when we need to begin planning our Theater in the Park series for the summer.","start":6.12,"end":11.49,"clipSrc":"../../audio-sentences/t2-35-s01.mp3","clipSourceStart":6.04},{"id":"t2-35-u02","speaker":"W","text":"We have lots of decisions to make about shows, dates, and performers.","start":12.15,"end":16.05,"clipSrc":"../../audio-sentences/t2-35-s02.mp3","clipSourceStart":12.07},{"id":"t2-35-u03","speaker":"M","text":"You're right. I'll set up a meeting for this month.","start":16.59,"end":19.47,"clipSrc":"../../audio-sentences/t2-35-meaning-03.mp3","clipSourceStart":16.51},{"id":"t2-35-u04","speaker":"M","text":"You know, I had an idea.","start":19.92,"end":21.69,"clipSrc":"../../audio-sentences/t2-35-s05.mp3","clipSourceStart":19.84},{"id":"t2-35-u05","speaker":"M","text":"Why don't we invite community residents to volunteer to help with building sets, painting, and setting up the stage?","start":22.29,"end":28.17,"clipSrc":"../../audio-sentences/t2-35-s06.mp3","clipSourceStart":22.21},{"id":"t2-35-u06","speaker":"W","text":"We could, but I don't know if we'll be able to use volunteers this year.","start":28.32,"end":32.58,"clipSrc":"../../audio-sentences/t2-35-s07.mp3","clipSourceStart":28.24},{"id":"t2-35-u07","speaker":"W","text":"We'll need approval to start that kind of program.","start":33.12,"end":35.43,"clipSrc":"../../audio-sentences/t2-35-s08.mp3","clipSourceStart":33.04},{"id":"t2-35-u08","speaker":"W","text":"It'll take time. Let's check into that for next year.","start":36.06,"end":39.33,"clipSrc":"../../audio-sentences/t2-35-meaning-08.mp3","clipSourceStart":35.98}]},"t2-38":{"conversationId":"t2-38","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[9,10]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-38-u01","speaker":"M","text":"Back to our podcast with special guest Kimberly Stuart, who's currently advising our city on business development projects.","start":5.49,"end":12.75,"clipSrc":"../../audio-sentences/t2-38-s01.mp3","clipSourceStart":5.41},{"id":"t2-38-u02","speaker":"M","text":"Before the break, we promised to address the decline of shopping downtown.","start":13.2,"end":17.61,"clipSrc":"../../audio-sentences/t2-38-s02.mp3","clipSourceStart":13.12},{"id":"t2-38-u03","speaker":"W","text":"Yes—and it's been the worst at the kind of stores that sell unique items like antiques and jewelry.","start":17.97,"end":23.91,"clipSrc":"../../audio-sentences/t2-38-s03.mp3","clipSourceStart":17.89},{"id":"t2-38-u04","speaker":"W","text":"These items have always been purchased at brick-and-mortar stores but are now being purchased mostly online.","start":24.39,"end":30.87,"clipSrc":"../../audio-sentences/t2-38-s04.mp3","clipSourceStart":24.31},{"id":"t2-38-u05","speaker":"M","text":"So, do those stores have a future?","start":31.29,"end":33.33,"clipSrc":"../../audio-sentences/t2-38-s05.mp3","clipSourceStart":31.21},{"id":"t2-38-u06","speaker":"W","text":"I think they do, especially if we make a point of organizing live community activities downtown, such as concerts or festivals.","start":33.75,"end":41.94,"clipSrc":"../../audio-sentences/t2-38-s06.mp3","clipSourceStart":33.67},{"id":"t2-38-u07","speaker":"W","text":"When people walk around town, they are likely to browse at stores—and make purchases.","start":42.39,"end":47.52,"clipSrc":"../../audio-sentences/t2-38-s07.mp3","clipSourceStart":42.31}]},"t2-41":{"conversationId":"t2-41","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[10,11]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-41-u01","speaker":"M","text":"Our company has seen a huge spike in sales ever since it launched the rebate program for customers.","start":5.85,"end":11.1,"clipSrc":"../../audio-sentences/t2-41-s01.mp3","clipSourceStart":5.77},{"id":"t2-41-u02","speaker":"M","text":"With the rebate, customers get money back.","start":11.55,"end":13.98,"clipSrc":"../../audio-sentences/t2-41-s02.mp3","clipSourceStart":11.47},{"id":"t2-41-u03","speaker":"M","text":"And they're telling their friends, increasing our sales.","start":14.4,"end":16.95,"clipSrc":"../../audio-sentences/t2-41-s03.mp3","clipSourceStart":14.32},{"id":"t2-41-u04","speaker":"W","text":"Yes. The rebate's been great for our company because now more homeowners have an incentive to install solar panels on their properties, since they're rewarded for the electricity their solar panels produce.","start":17.37,"end":28.38,"clipSrc":"../../audio-sentences/t2-41-meaning-04.mp3","clipSourceStart":17.29},{"id":"t2-41-u05","speaker":"W","text":"But our technicians can't keep up with the high demand.","start":28.77,"end":31.68,"clipSrc":"../../audio-sentences/t2-41-s06.mp3","clipSourceStart":28.69},{"id":"t2-41-u06","speaker":"M","text":"You're right. I'm planning to hire more technicians.","start":32.1,"end":35.13,"clipSrc":"../../audio-sentences/t2-41-meaning-06.mp3","clipSourceStart":32.02},{"id":"t2-41-u07","speaker":"M","text":"I've already received some résumés from potential candidates.","start":35.43,"end":38.43,"clipSrc":"../../audio-sentences/t2-41-s09.mp3","clipSourceStart":35.35}]},"t2-44":{"conversationId":"t2-44","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[11,12]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-44-u01","speaker":"M","text":"Fernanda, I was just looking at the company calendar, and I noticed that the national electronics trade show is coming up soon.","start":6.06,"end":13.14,"clipSrc":"../../audio-sentences/t2-44-s01.mp3","clipSourceStart":5.98},{"id":"t2-44-u02","speaker":"W","text":"Oh, that's right! It'll be a great opportunity for us to showcase the product that we've been developing—our new robotic vacuum cleaner.","start":13.56,"end":21.45,"clipSrc":"../../audio-sentences/t2-44-s02.mp3","clipSourceStart":13.48},{"id":"t2-44-u03","speaker":"M","text":"We'll need to decide who we want to send to represent our company at the trade show.","start":21.93,"end":26.55,"clipSrc":"../../audio-sentences/t2-44-s03.mp3","clipSourceStart":21.85},{"id":"t2-44-u04","speaker":"W","text":"Well, I know just the right person—Kavi.","start":26.91,"end":29.85,"clipSrc":"../../audio-sentences/t2-44-s04.mp3","clipSourceStart":26.83},{"id":"t2-44-u05","speaker":"W","text":"Kavi does a good job of clearly explaining highly technical concepts in a way that everyone can understand.","start":30.3,"end":36.06,"clipSrc":"../../audio-sentences/t2-44-s05.mp3","clipSourceStart":30.22}]},"t2-47":{"conversationId":"t2-47","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[12,13]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-47-u01","speaker":"M","text":"Dr. Fuentes, sorry to interrupt.","start":6.09,"end":8.25,"clipSrc":"../../audio-sentences/t2-47-s01.mp3","clipSourceStart":6.01},{"id":"t2-47-u02","speaker":"M","text":"Do you have a minute?","start":8.28,"end":9.15,"clipSrc":"../../audio-sentences/t2-47-s02.mp3","clipSourceStart":8.25},{"id":"t2-47-u03","speaker":"W","text":"Yes. My nine o'clock dental cleaning patient just canceled.","start":9.51,"end":12.9,"clipSrc":"../../audio-sentences/t2-47-meaning-03.mp3","clipSourceStart":9.43},{"id":"t2-47-u04","speaker":"M","text":"I know you're looking for a new receptionist.","start":13.38,"end":15.36,"clipSrc":"../../audio-sentences/t2-47-s05.mp3","clipSourceStart":13.3},{"id":"t2-47-u05","speaker":"M","text":"I'd like to recommend someone for the position.","start":15.81,"end":17.88,"clipSrc":"../../audio-sentences/t2-47-s06.mp3","clipSourceStart":15.73},{"id":"t2-47-u06","speaker":"W","text":"Oh. Who do you have in mind?","start":18.09,"end":19.92,"clipSrc":"../../audio-sentences/t2-47-meaning-06.mp3","clipSourceStart":18.01},{"id":"t2-47-u07","speaker":"M","text":"Well, a former colleague of mine has just moved back to town.","start":20.37,"end":23.76,"clipSrc":"../../audio-sentences/t2-47-s09.mp3","clipSourceStart":20.29},{"id":"t2-47-u08","speaker":"M","text":"Her name's Kelly Graham, and she has several years of experience.","start":24.24,"end":28.11,"clipSrc":"../../audio-sentences/t2-47-s10.mp3","clipSourceStart":24.16},{"id":"t2-47-u09","speaker":"W","text":"OK. Could you tell Kelly to send me her résumé? I'd be happy to look it over.","start":28.29,"end":33.06,"clipSrc":"../../audio-sentences/t2-47-meaning-09.mp3","clipSourceStart":28.21}]},"t2-50":{"conversationId":"t2-50","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[13,14]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-50-u01","speaker":"M1","text":"Ms. Gao? I'm Hector, and this is my colleague Sergey.","start":7.08,"end":10.5,"clipSrc":"../../audio-sentences/t2-50-s01.mp3","clipSourceStart":7},{"id":"t2-50-u02","speaker":"M1","text":"Thanks for meeting with us.","start":10.68,"end":11.94,"clipSrc":"../../audio-sentences/t2-50-s02.mp3","clipSourceStart":10.6},{"id":"t2-50-u03","speaker":"W","text":"It's a pleasure to meet you both.","start":12.27,"end":13.95,"clipSrc":"../../audio-sentences/t2-50-s03.mp3","clipSourceStart":12.19},{"id":"t2-50-u04","speaker":"W","text":"How can I help you?","start":14.43,"end":15.39,"clipSrc":"../../audio-sentences/t2-50-s04.mp3","clipSourceStart":14.35},{"id":"t2-50-u05","speaker":"M2","text":"We're making some training videos for our client, FiveStar Industries.","start":15.87,"end":19.53,"clipSrc":"../../audio-sentences/t2-50-s05.mp3","clipSourceStart":15.79},{"id":"t2-50-u06","speaker":"M1","text":"We found your advertisement in a trade publication.","start":19.98,"end":22.68,"clipSrc":"../../audio-sentences/t2-50-s06.mp3","clipSourceStart":19.9},{"id":"t2-50-u07","speaker":"M1","text":"We need someone to choose appropriate filming sites at FiveStar's factories, and it said you have lots of experience scouting for industrial locations.","start":23.1,"end":31.38,"clipSrc":"../../audio-sentences/t2-50-s07.mp3","clipSourceStart":23.02},{"id":"t2-50-u08","speaker":"W","text":"Sure. I'd want to start by touring their factories.","start":31.95,"end":34.86,"clipSrc":"../../audio-sentences/t2-50-meaning-08.mp3","clipSourceStart":31.87},{"id":"t2-50-u09","speaker":"W","text":"Can you schedule a time for me to do that next week?","start":35.19,"end":37.65,"clipSrc":"../../audio-sentences/t2-50-s10.mp3","clipSourceStart":35.11},{"id":"t2-50-u10","speaker":"M2","text":"Yes, I'll call them today to arrange it.","start":38.19,"end":40.77,"clipSrc":"../../audio-sentences/t2-50-s11.mp3","clipSourceStart":38.11}]},"t2-53":{"conversationId":"t2-53","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[14,15]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-53-u01","speaker":"M","text":"Our engineering firm has been asked to cut the corporate travel budget by twenty percent, but it won't be easy.","start":6,"end":12.12,"clipSrc":"../../audio-sentences/t2-53-s01.mp3","clipSourceStart":5.92},{"id":"t2-53-u02","speaker":"M","text":"The engineering consultants have to travel to meet with clients.","start":12.51,"end":15.6,"clipSrc":"../../audio-sentences/t2-53-s02.mp3","clipSourceStart":12.43},{"id":"t2-53-u03","speaker":"W","text":"Right, and they often travel on short notice.","start":15.96,"end":18.45,"clipSrc":"../../audio-sentences/t2-53-s03.mp3","clipSourceStart":15.88},{"id":"t2-53-u04","speaker":"W","text":"Flight arrangements made at the last minute are expensive, especially for nonstop flights.","start":18.81,"end":23.34,"clipSrc":"../../audio-sentences/t2-53-s04.mp3","clipSourceStart":18.73},{"id":"t2-53-u05","speaker":"W","text":"It would be cheaper if they took connecting flights.","start":23.79,"end":26.31,"clipSrc":"../../audio-sentences/t2-53-s05.mp3","clipSourceStart":23.71},{"id":"t2-53-u06","speaker":"M","text":"Yes, but that can take a lot of time.","start":26.76,"end":29.37,"clipSrc":"../../audio-sentences/t2-53-s06.mp3","clipSourceStart":26.68},{"id":"t2-53-u07","speaker":"W","text":"True. Maybe we can make up for the cost of the flights by economizing on hotels.","start":29.61,"end":35.07,"clipSrc":"../../audio-sentences/t2-53-meaning-07.mp3","clipSourceStart":29.53},{"id":"t2-53-u08","speaker":"W","text":"Let's look into that.","start":35.61,"end":36.78,"clipSrc":"../../audio-sentences/t2-53-s09.mp3","clipSourceStart":35.53}]},"t2-56":{"conversationId":"t2-56","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[15,16]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-56-u01","speaker":"M1","text":"Thanks for meeting with us, Ms. Azuma.","start":7.17,"end":9.09,"clipSrc":"../../audio-sentences/t2-56-s01.mp3","clipSourceStart":7.09},{"id":"t2-56-u02","speaker":"M1","text":"This is Scott Ajibade, one of our senior project managers.","start":9.39,"end":12.99,"clipSrc":"../../audio-sentences/t2-56-s02.mp3","clipSourceStart":9.31},{"id":"t2-56-u03","speaker":"M2","text":"I admire your work, Ms. Azuma.","start":13.53,"end":15.51,"clipSrc":"../../audio-sentences/t2-56-s03.mp3","clipSourceStart":13.45},{"id":"t2-56-u04","speaker":"W","text":"Thank you. I was surprised by your invitation.","start":15.93,"end":19.17,"clipSrc":"../../audio-sentences/t2-56-meaning-04.mp3","clipSourceStart":15.85},{"id":"t2-56-u05","speaker":"W","text":"I typically design jewelry, but your company's known for making computers and mobile phones.","start":19.74,"end":24.87,"clipSrc":"../../audio-sentences/t2-56-s06.mp3","clipSourceStart":19.66},{"id":"t2-56-u06","speaker":"M1","text":"Scott's team is currently working on a smartwatch.","start":25.29,"end":28.08,"clipSrc":"../../audio-sentences/t2-56-s07.mp3","clipSourceStart":25.21},{"id":"t2-56-u07","speaker":"M1","text":"But there's a lot of competition, as you know.","start":28.47,"end":30.81,"clipSrc":"../../audio-sentences/t2-56-s08.mp3","clipSourceStart":28.39},{"id":"t2-56-u08","speaker":"M2","text":"We're hoping you can create a fresh design that will help our product stand out.","start":31.17,"end":35.28,"clipSrc":"../../audio-sentences/t2-56-s09.mp3","clipSourceStart":31.09},{"id":"t2-56-u09","speaker":"W","text":"Do you already have an idea of what the watch should look like, or are we starting from scratch?","start":35.88,"end":40.59,"clipSrc":"../../audio-sentences/t2-56-s10.mp3","clipSourceStart":35.8},{"id":"t2-56-u10","speaker":"M2","text":"I have some preliminary sketches we can look at, but none of them seem quite right.","start":41.16,"end":45.87,"clipSrc":"../../audio-sentences/t2-56-s11.mp3","clipSourceStart":41.08}]},"t2-59":{"conversationId":"t2-59","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[17,18]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-59-u01","speaker":"W","text":"Hi. I'd like to purchase some new carpeting.","start":6,"end":8.91,"clipSrc":"../../audio-sentences/t2-59-meaning-01.mp3","clipSourceStart":5.92},{"id":"t2-59-u02","speaker":"W","text":"It's for the waiting room at my hair salon.","start":9.27,"end":11.46,"clipSrc":"../../audio-sentences/t2-59-s03.mp3","clipSourceStart":9.19},{"id":"t2-59-u03","speaker":"M","text":"We have many different styles.","start":11.97,"end":13.71,"clipSrc":"../../audio-sentences/t2-59-s04.mp3","clipSourceStart":11.89},{"id":"t2-59-u04","speaker":"M","text":"Are you looking for something different?","start":14.1,"end":15.78,"clipSrc":"../../audio-sentences/t2-59-s05.mp3","clipSourceStart":14.02},{"id":"t2-59-u05","speaker":"W","text":"Well, we get a lot of customers walking through, and our current carpeting is a light color.","start":16.08,"end":22.59,"clipSrc":"../../audio-sentences/t2-59-s06.mp3","clipSourceStart":16},{"id":"t2-59-u06","speaker":"M","text":"No matter what color you get, all our carpets are durable and can take high amounts of foot traffic.","start":23.28,"end":29.19,"clipSrc":"../../audio-sentences/t2-59-s07.mp3","clipSourceStart":23.2},{"id":"t2-59-u07","speaker":"M","text":"For businesses like yours, I recommend placing a protective mat near the door.","start":29.7,"end":34.56,"clipSrc":"../../audio-sentences/t2-59-s08.mp3","clipSourceStart":29.62},{"id":"t2-59-u08","speaker":"W","text":"That's a good idea.","start":34.95,"end":36.03,"clipSrc":"../../audio-sentences/t2-59-s09.mp3","clipSourceStart":34.87},{"id":"t2-59-u09","speaker":"M","text":"Also, I offer free cleaning services for a year for all purchases.","start":36.42,"end":40.86,"clipSrc":"../../audio-sentences/t2-59-s10.mp3","clipSourceStart":36.34}]},"t2-62":{"conversationId":"t2-62","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[18,19]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-62-u01","speaker":"M","text":"I really need this coffee break.","start":6.96,"end":8.67,"clipSrc":"../../audio-sentences/t2-62-s01.mp3","clipSourceStart":6.88},{"id":"t2-62-u02","speaker":"M","text":"My morning meeting with my client was really challenging.","start":9.09,"end":12.72,"clipSrc":"../../audio-sentences/t2-62-s02.mp3","clipSourceStart":9.01},{"id":"t2-62-u03","speaker":"W","text":"What were you discussing?","start":13.2,"end":14.52,"clipSrc":"../../audio-sentences/t2-62-s03.mp3","clipSourceStart":13.12},{"id":"t2-62-u04","speaker":"M","text":"The project schedule. They asked us to provide the prototype design to them three weeks earlier than originally planned.","start":14.73,"end":21.3,"clipSrc":"../../audio-sentences/t2-62-meaning-04.mp3","clipSourceStart":14.65},{"id":"t2-62-u05","speaker":"W","text":"Well. Then today's cup is my treat.","start":21.87,"end":23.97,"clipSrc":"../../audio-sentences/t2-62-meaning-05.mp3","clipSourceStart":21.79},{"id":"t2-62-u06","speaker":"W","text":"Which one would you like?","start":24.39,"end":25.38,"clipSrc":"../../audio-sentences/t2-62-s08.mp3","clipSourceStart":24.31},{"id":"t2-62-u07","speaker":"M","text":"That's so nice of you! I'll go with the White Cloud Coffee.","start":25.83,"end":29.67,"clipSrc":"../../audio-sentences/t2-62-s09.mp3","clipSourceStart":25.75},{"id":"t2-62-u08","speaker":"M","text":"I like a little milk in mine.","start":30.06,"end":31.5,"clipSrc":"../../audio-sentences/t2-62-s10.mp3","clipSourceStart":29.98},{"id":"t2-62-u09","speaker":"W","text":"Good choice. So, I have some news to share with you.","start":31.8,"end":35.01,"clipSrc":"../../audio-sentences/t2-62-meaning-09.mp3","clipSourceStart":31.72},{"id":"t2-62-u10","speaker":"W","text":"Did you hear about David?","start":35.52,"end":36.84,"clipSrc":"../../audio-sentences/t2-62-s13.mp3","clipSourceStart":35.44},{"id":"t2-62-u11","speaker":"M","text":"No, what's going on?","start":37.11,"end":38.61,"clipSrc":"../../audio-sentences/t2-62-s14.mp3","clipSourceStart":37.03},{"id":"t2-62-u12","speaker":"W","text":"Apparently, he's planning to retire next month.","start":38.88,"end":41.67,"clipSrc":"../../audio-sentences/t2-62-s15.mp3","clipSourceStart":38.8}]},"t2-65":{"conversationId":"t2-65","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[19,20]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-65-u01","speaker":"M","text":"This is Bradley from Windows Galore.","start":7.05,"end":8.82,"clipSrc":"../../audio-sentences/t2-65-s01.mp3","clipSourceStart":6.97},{"id":"t2-65-u02","speaker":"M","text":"How can I help you?","start":8.91,"end":9.84,"clipSrc":"../../audio-sentences/t2-65-s02.mp3","clipSourceStart":8.83},{"id":"t2-65-u03","speaker":"W","text":"Hello! I'd like to have screens added to my windows at home.","start":10.17,"end":14.19,"clipSrc":"../../audio-sentences/t2-65-s03.mp3","clipSourceStart":10.09},{"id":"t2-65-u04","speaker":"W","text":"I was wondering if you would be available to stop by and take a look.","start":14.73,"end":18.24,"clipSrc":"../../audio-sentences/t2-65-s04.mp3","clipSourceStart":14.65},{"id":"t2-65-u05","speaker":"W","text":"I live at 42 West Third Street, by the way.","start":18.78,"end":21.9,"clipSrc":"../../audio-sentences/t2-65-s05.mp3","clipSourceStart":18.7},{"id":"t2-65-u06","speaker":"M","text":"OK—that's not far.","start":22.47,"end":24,"clipSrc":"../../audio-sentences/t2-65-s06.mp3","clipSourceStart":22.39},{"id":"t2-65-u07","speaker":"M","text":"Let me see. I could come any morning this week.","start":24.21,"end":27.03,"clipSrc":"../../audio-sentences/t2-65-meaning-07.mp3","clipSourceStart":24.13},{"id":"t2-65-u08","speaker":"W","text":"How about in the afternoon?","start":27.84,"end":29.37,"clipSrc":"../../audio-sentences/t2-65-s09.mp3","clipSourceStart":27.76},{"id":"t2-65-u09","speaker":"M","text":"Hmm. I could reschedule my Tuesday afternoon appointment.","start":29.93,"end":33.33,"clipSrc":"../../audio-sentences/t2-65-meaning-09.mp3","clipSourceStart":29.85},{"id":"t2-65-u10","speaker":"M","text":"I'll check and get back to you—I have your number now.","start":33.6,"end":36.51,"clipSrc":"../../audio-sentences/t2-65-s12.mp3","clipSourceStart":33.52},{"id":"t2-65-u11","speaker":"M","text":"And your name is?","start":36.66,"end":37.53,"clipSrc":"../../audio-sentences/t2-65-s13.mp3","clipSourceStart":36.58},{"id":"t2-65-u12","speaker":"W","text":"Hoffman—Claudia Hoffman. Thank you.","start":37.71,"end":40.47,"clipSrc":"../../audio-sentences/t2-65-meaning-12.mp3","clipSourceStart":37.63},{"id":"t2-65-u13","speaker":"W","text":"Talk to you soon.","start":40.71,"end":41.55,"clipSrc":"../../audio-sentences/t2-65-s16.mp3","clipSourceStart":40.63}]},"t2-68":{"conversationId":"t2-68","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 2 ets 2026.pdf","pages":[21,22]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t2-68-u01","speaker":"M","text":"Ms. Kwon, thank you for sending me to the upcoming robotics conference.","start":6.57,"end":10.5,"clipSrc":"../../audio-sentences/t2-68-s01.mp3","clipSourceStart":6.49},{"id":"t2-68-u02","speaker":"M","text":"I didn't expect an opportunity like this so soon after being hired here.","start":10.92,"end":14.67,"clipSrc":"../../audio-sentences/t2-68-s02.mp3","clipSourceStart":10.84},{"id":"t2-68-u03","speaker":"W","text":"It's important for you to be familiar with current robot designs.","start":14.97,"end":18.6,"clipSrc":"../../audio-sentences/t2-68-s03.mp3","clipSourceStart":14.89},{"id":"t2-68-u04","speaker":"W","text":"There are always new trends and technologies coming out, and I want you to stay ahead of developments in our industry.","start":19.14,"end":24.6,"clipSrc":"../../audio-sentences/t2-68-s04.mp3","clipSourceStart":19.06},{"id":"t2-68-u05","speaker":"M","text":"I agree. Plus, it'll give me the chance to introduce myself to potential clients.","start":25.11,"end":29.97,"clipSrc":"../../audio-sentences/t2-68-meaning-05.mp3","clipSourceStart":25.03},{"id":"t2-68-u06","speaker":"W","text":"Oh, about that: here's a handout I provide to all new hires.","start":30.27,"end":34.47,"clipSrc":"../../audio-sentences/t2-68-s07.mp3","clipSourceStart":30.19},{"id":"t2-68-u07","speaker":"W","text":"It includes some helpful tips— especially this one.","start":34.83,"end":37.62,"clipSrc":"../../audio-sentences/t2-68-s08.mp3","clipSourceStart":34.75},{"id":"t2-68-u08","speaker":"W","text":"Do you have your business cards yet?","start":38.1,"end":39.75,"clipSrc":"../../audio-sentences/t2-68-s09.mp3","clipSourceStart":38.02},{"id":"t2-68-u09","speaker":"M","text":"Hmm. I haven't received them, but I'll call the printer today for an update.","start":40.32,"end":44.4,"clipSrc":"../../audio-sentences/t2-68-meaning-09.mp3","clipSourceStart":40.24}]},"t3-32":{"conversationId":"t3-32","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[8,9]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-32-u01","speaker":"M","text":"Hi, Chef Ayaka. I was looking over this week's sales, and I noticed that a lot of people ordered the beef stew special.","start":6,"end":12.75,"clipSrc":"../../audio-sentences/t3-32-meaning-01.mp3","clipSourceStart":5.92},{"id":"t3-32-u02","speaker":"W","text":"Yeah. It's been very popular with patrons.","start":12.93,"end":15.78,"clipSrc":"../../audio-sentences/t3-32-meaning-02.mp3","clipSourceStart":12.85},{"id":"t3-32-u03","speaker":"W","text":"In fact, I want to add it to the regular menu.","start":16.05,"end":18.48,"clipSrc":"../../audio-sentences/t3-32-s05.mp3","clipSourceStart":15.97},{"id":"t3-32-u04","speaker":"M","text":"Good idea. Beef prices change frequently, though, so we might need to consider that when we set the price for the dish if we're going to offer it daily.","start":18.72,"end":27.36,"clipSrc":"../../audio-sentences/t3-32-meaning-04.mp3","clipSourceStart":18.64},{"id":"t3-32-u05","speaker":"W","text":"OK. I'll call our supplier too.","start":27.84,"end":30.03,"clipSrc":"../../audio-sentences/t3-32-meaning-05.mp3","clipSourceStart":27.76},{"id":"t3-32-u06","speaker":"W","text":"We need to make sure they can get us enough beef each week.","start":30.36,"end":33.48,"clipSrc":"../../audio-sentences/t3-32-s10.mp3","clipSourceStart":30.28}]},"t3-35":{"conversationId":"t3-35","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[9,10]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-35-u01","speaker":"M1","text":"Excuse me, does train 1401 stop at the Lexington Street station?","start":7.38,"end":11.79,"clipSrc":"../../audio-sentences/t3-35-s01.mp3","clipSourceStart":7.3},{"id":"t3-35-u02","speaker":"W","text":"Yes. It's a twenty-minute ride.","start":12.06,"end":14.1,"clipSrc":"../../audio-sentences/t3-35-meaning-02.mp3","clipSourceStart":11.98},{"id":"t3-35-u03","speaker":"M2","text":"Oh good, that gives us plenty of time to get to the party.","start":14.67,"end":18.03,"clipSrc":"../../audio-sentences/t3-35-s04.mp3","clipSourceStart":14.59},{"id":"t3-35-u04","speaker":"W","text":"The train leaves from platform twelve in three minutes.","start":18.24,"end":21.21,"clipSrc":"../../audio-sentences/t3-35-s05.mp3","clipSourceStart":18.16},{"id":"t3-35-u05","speaker":"M2","text":"Let's head over there now, Sergey.","start":21.42,"end":23.1,"clipSrc":"../../audio-sentences/t3-35-s06.mp3","clipSourceStart":21.34},{"id":"t3-35-u06","speaker":"M2","text":"I'm really looking forward to our company gala event tonight.","start":23.43,"end":26.64,"clipSrc":"../../audio-sentences/t3-35-s07.mp3","clipSourceStart":23.35},{"id":"t3-35-u07","speaker":"M1","text":"Me too. Hey, did you happen to bring an umbrella? I forgot mine.","start":26.88,"end":30.99,"clipSrc":"../../audio-sentences/t3-35-meaning-07.mp3","clipSourceStart":26.8},{"id":"t3-35-u08","speaker":"M1","text":"It might rain on our walk from the station.","start":31.26,"end":33.42,"clipSrc":"../../audio-sentences/t3-35-s10.mp3","clipSourceStart":31.18},{"id":"t3-35-u09","speaker":"M2","text":"I did! We can share it.","start":33.81,"end":35.52,"clipSrc":"../../audio-sentences/t3-35-s11.mp3","clipSourceStart":33.73}]},"t3-38":{"conversationId":"t3-38","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[10,11]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-38-u01","speaker":"W","text":"I talked to Mr. Hoffman this morning, and he said he's decided to start a delivery service for our customers who have a difficult time picking up their prescriptions.","start":5.52,"end":14.97,"clipSrc":"../../audio-sentences/t3-38-s01.mp3","clipSourceStart":5.44},{"id":"t3-38-u02","speaker":"M","text":"That's a good idea.","start":15.15,"end":16.38,"clipSrc":"../../audio-sentences/t3-38-s02.mp3","clipSourceStart":15.07},{"id":"t3-38-u03","speaker":"M","text":"I know a lot of people find it inconvenient to come in person to get their medications.","start":16.92,"end":21.45,"clipSrc":"../../audio-sentences/t3-38-s03.mp3","clipSourceStart":16.84},{"id":"t3-38-u04","speaker":"M","text":"But many of our customers buy other things while they're here.","start":21.75,"end":25.17,"clipSrc":"../../audio-sentences/t3-38-s04.mp3","clipSourceStart":21.67},{"id":"t3-38-u05","speaker":"W","text":"Oh, they'll be able to make other purchases too, to be delivered with their medicine.","start":25.5,"end":30.27,"clipSrc":"../../audio-sentences/t3-38-s05.mp3","clipSourceStart":25.42},{"id":"t3-38-u06","speaker":"W","text":"In fact, I'm supposed to draft a job posting for delivery drivers.","start":30.84,"end":35.01,"clipSrc":"../../audio-sentences/t3-38-s06.mp3","clipSourceStart":30.76},{"id":"t3-38-u07","speaker":"W","text":"Could you help me do that?","start":35.4,"end":36.72,"clipSrc":"../../audio-sentences/t3-38-s07.mp3","clipSourceStart":35.32}]},"t3-41":{"conversationId":"t3-41","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[11,12]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-41-u01","speaker":"W","text":"Marcel, I don't know if you reviewed the latest report.","start":5.85,"end":9.51,"clipSrc":"../../audio-sentences/t3-41-s01.mp3","clipSourceStart":5.77},{"id":"t3-41-u02","speaker":"W","text":"Unfortunately, our sales are continuing to drop.","start":9.78,"end":13.08,"clipSrc":"../../audio-sentences/t3-41-s02.mp3","clipSourceStart":9.7},{"id":"t3-41-u03","speaker":"M","text":"Yes, competition is at an all-time high.","start":13.59,"end":16.65,"clipSrc":"../../audio-sentences/t3-41-s03.mp3","clipSourceStart":13.51},{"id":"t3-41-u04","speaker":"M","text":"More and more companies are selling clothing and gear for outdoor recreation.","start":17.16,"end":20.82,"clipSrc":"../../audio-sentences/t3-41-s04.mp3","clipSourceStart":17.08},{"id":"t3-41-u05","speaker":"W","text":"We need better ways to make our brand stand out.","start":21.27,"end":24.57,"clipSrc":"../../audio-sentences/t3-41-s05.mp3","clipSourceStart":21.19},{"id":"t3-41-u06","speaker":"M","text":"Well, we could probably benefit from having more direct input from athletes who use our gear.","start":25.02,"end":30.36,"clipSrc":"../../audio-sentences/t3-41-s06.mp3","clipSourceStart":24.94},{"id":"t3-41-u07","speaker":"M","text":"I was thinking maybe we could hire a professional rock climber to consult with our designers.","start":30.99,"end":35.64,"clipSrc":"../../audio-sentences/t3-41-s07.mp3","clipSourceStart":30.91},{"id":"t3-41-u08","speaker":"W","text":"That's an interesting idea.","start":36.06,"end":37.83,"clipSrc":"../../audio-sentences/t3-41-s08.mp3","clipSourceStart":35.98},{"id":"t3-41-u09","speaker":"W","text":"Is there anyone you have in mind?","start":38.16,"end":40.02,"clipSrc":"../../audio-sentences/t3-41-s09.mp3","clipSourceStart":38.08},{"id":"t3-41-u10","speaker":"M","text":"I'll e-mail you a list this afternoon.","start":40.2,"end":42.24,"clipSrc":"../../audio-sentences/t3-41-s10.mp3","clipSourceStart":40.12}]},"t3-44":{"conversationId":"t3-44","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[12,13]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-44-u01","speaker":"W","text":"Hello. I was featured in an article in your newspaper about five years ago.","start":6.09,"end":10.68,"clipSrc":"../../audio-sentences/t3-44-meaning-01.mp3","clipSourceStart":6.01},{"id":"t3-44-u02","speaker":"W","text":"And now when I click on the link, nothing happens.","start":11.01,"end":13.74,"clipSrc":"../../audio-sentences/t3-44-s03.mp3","clipSourceStart":10.93},{"id":"t3-44-u03","speaker":"M","text":"Oh, the public links expire after three years, but I can search for your article in our database.","start":14.01,"end":20.07,"clipSrc":"../../audio-sentences/t3-44-s04.mp3","clipSourceStart":13.93},{"id":"t3-44-u04","speaker":"M","text":"I just need keywords from the article to use in the search.","start":20.37,"end":23.58,"clipSrc":"../../audio-sentences/t3-44-s05.mp3","clipSourceStart":20.29},{"id":"t3-44-u05","speaker":"W","text":"It was about my internship at a dental office.","start":23.91,"end":26.82,"clipSrc":"../../audio-sentences/t3-44-s06.mp3","clipSourceStart":23.83},{"id":"t3-44-u06","speaker":"M","text":"OK. Let me check our archives.","start":27.06,"end":29.31,"clipSrc":"../../audio-sentences/t3-44-meaning-06.mp3","clipSourceStart":26.98},{"id":"t3-44-u07","speaker":"W","text":"Thanks. I was still in college when the article came out, but now I'm starting my own practice.","start":29.55,"end":35.16,"clipSrc":"../../audio-sentences/t3-44-meaning-07.mp3","clipSourceStart":29.47},{"id":"t3-44-u08","speaker":"W","text":"And I'd like to hang the article on the wall.","start":35.37,"end":37.41,"clipSrc":"../../audio-sentences/t3-44-s11.mp3","clipSourceStart":35.29},{"id":"t3-44-u09","speaker":"M","text":"Oh! Congratulations.","start":37.68,"end":39.54,"clipSrc":"../../audio-sentences/t3-44-s12.mp3","clipSourceStart":37.6}]},"t3-47":{"conversationId":"t3-47","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[13,14],"transcriptCorrection":{"file":"C:\\Users\\Nam\\Documents\\transcript 2026 ets.pdf","pages":[76],"reason":"Supplied individual Test 3 PDF contains unrelated transcript for 47-49. Scan read visually and checked against audio."}},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-47-u01","speaker":"W","text":"Welcome to Scott's Supplies! Just so you know, all our power tools and ladders are twenty percent off today.","start":6.06,"end":13.71,"clipSrc":"../../audio-sentences/t3-47-s01.mp3","clipSourceStart":5.98},{"id":"t3-47-u02","speaker":"W","text":"Is there something I can help you with?","start":14.04,"end":15.72,"clipSrc":"../../audio-sentences/t3-47-s02.mp3","clipSourceStart":13.96},{"id":"t3-47-u03","speaker":"M","text":"Yes. I came in last week to get some lumber for a home project I was working on, but the boards I purchased are the wrong width.","start":15.99,"end":23.58,"clipSrc":"../../audio-sentences/t3-47-meaning-03.mp3","clipSourceStart":15.91},{"id":"t3-47-u04","speaker":"M","text":"I was wondering if I could get a refund.","start":23.88,"end":25.89,"clipSrc":"../../audio-sentences/t3-47-s05.mp3","clipSourceStart":23.8},{"id":"t3-47-u05","speaker":"W","text":"Sure. Do you have the receipt?","start":26.07,"end":28.05,"clipSrc":"../../audio-sentences/t3-47-meaning-05.mp3","clipSourceStart":25.99},{"id":"t3-47-u06","speaker":"M","text":"No, unfortunately. I must've lost it.","start":28.23,"end":31.11,"clipSrc":"../../audio-sentences/t3-47-meaning-06.mp3","clipSourceStart":28.15},{"id":"t3-47-u07","speaker":"W","text":"Hmm, OK. Let me find the manager.","start":31.68,"end":34.5,"clipSrc":"../../audio-sentences/t3-47-meaning-07.mp3","clipSourceStart":31.6}]},"t3-50":{"conversationId":"t3-50","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[14,15],"transcriptCorrection":{"file":"C:\\Users\\Nam\\Documents\\transcript 2026 ets.pdf","pages":[77],"reason":"Supplied individual Test 3 PDF contains unrelated transcript for 50-52. Scan read visually and checked against audio."}},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-50-u01","speaker":"W","text":"Welcome back! How were your lunch deliveries?","start":5.82,"end":8.37,"clipSrc":"../../audio-sentences/t3-50-s01.mp3","clipSourceStart":5.74},{"id":"t3-50-u02","speaker":"M","text":"All right, except one bag broke and the food container fell out right as I was walking up to a customer’s door.","start":8.88,"end":15.24,"clipSrc":"../../audio-sentences/t3-50-s02.mp3","clipSourceStart":8.8},{"id":"t3-50-u03","speaker":"M","text":"The container was still sealed, and the customer accepted it, so it turned out OK in the end.","start":15.75,"end":20.85,"clipSrc":"../../audio-sentences/t3-50-s03.mp3","clipSourceStart":15.67},{"id":"t3-50-u04","speaker":"W","text":"Well, I’m glad everything worked out.","start":21.15,"end":23.1,"clipSrc":"../../audio-sentences/t3-50-s04.mp3","clipSourceStart":21.07},{"id":"t3-50-u05","speaker":"W","text":"By the way, take a look at my screen! I got the new delivery software installed and running while you were gone.","start":23.61,"end":29.04,"clipSrc":"../../audio-sentences/t3-50-s05.mp3","clipSourceStart":23.53},{"id":"t3-50-u06","speaker":"M","text":"This looks great! I like how different areas can be grouped together so drivers can deliver more efficiently.","start":29.76,"end":35.79,"clipSrc":"../../audio-sentences/t3-50-s06.mp3","clipSourceStart":29.68},{"id":"t3-50-u07","speaker":"W","text":"Me too. And since we’ve recently had such a significant increase in customers, this will be really useful.","start":36.3,"end":42.54,"clipSrc":"../../audio-sentences/t3-50-meaning-07.mp3","clipSourceStart":36.22}]},"t3-53":{"conversationId":"t3-53","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[15,16]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-53-u01","speaker":"M","text":"Hi, Jin-Ah. I've got good news. We signed a contract to create an ad campaign for a new client.","start":5.97,"end":12.18,"clipSrc":"../../audio-sentences/t3-53-meaning-01.mp3","clipSourceStart":5.89},{"id":"t3-53-u02","speaker":"W","text":"That's great! Who is it?","start":12.45,"end":14.28,"clipSrc":"../../audio-sentences/t3-53-s04.mp3","clipSourceStart":12.37},{"id":"t3-53-u03","speaker":"M","text":"It's HMD Incorporated, an organic snack company.","start":14.46,"end":18.03,"clipSrc":"../../audio-sentences/t3-53-s05.mp3","clipSourceStart":14.38},{"id":"t3-53-u04","speaker":"M","text":"They just developed a new line of snacks made entirely from vegetables.","start":18.54,"end":22.35,"clipSrc":"../../audio-sentences/t3-53-s06.mp3","clipSourceStart":18.46},{"id":"t3-53-u05","speaker":"M","text":"They want to market the snacks to sports teams as well as individuals.","start":22.86,"end":26.67,"clipSrc":"../../audio-sentences/t3-53-s07.mp3","clipSourceStart":22.78},{"id":"t3-53-u06","speaker":"W","text":"Well, that sounds exciting but hard to understand.","start":26.94,"end":30.15,"clipSrc":"../../audio-sentences/t3-53-s08.mp3","clipSourceStart":26.86},{"id":"t3-53-u07","speaker":"W","text":"I guess we'll need to learn more about the products first.","start":30.66,"end":33.51,"clipSrc":"../../audio-sentences/t3-53-s09.mp3","clipSourceStart":30.58},{"id":"t3-53-u08","speaker":"M","text":"Exactly. We'll have the client come in to give us nutritional information, and provide us with some samples.","start":33.69,"end":39.69,"clipSrc":"../../audio-sentences/t3-53-meaning-08.mp3","clipSourceStart":33.61},{"id":"t3-53-u09","speaker":"M","text":"I'll schedule a meeting with them soon.","start":40.2,"end":42.21,"clipSrc":"../../audio-sentences/t3-53-s12.mp3","clipSourceStart":40.12}]},"t3-56":{"conversationId":"t3-56","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[16,17]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-56-u01","speaker":"W1","text":"Oliver, have you finished the maintenance check on the small airplane that came in this morning? The owner's hoping to fly it this weekend.","start":7.2,"end":14.94,"clipSrc":"../../audio-sentences/t3-56-s01.mp3","clipSourceStart":7.12},{"id":"t3-56-u02","speaker":"M","text":"I finished checking it earlier this morning.","start":15.51,"end":17.61,"clipSrc":"../../audio-sentences/t3-56-s02.mp3","clipSourceStart":15.43},{"id":"t3-56-u03","speaker":"M","text":"It needs a new fuel injection pump, so I've asked Camille to order one.","start":17.82,"end":21.39,"clipSrc":"../../audio-sentences/t3-56-s03.mp3","clipSourceStart":17.74},{"id":"t3-56-u04","speaker":"M","text":"Oh, here she comes.","start":21.93,"end":22.92,"clipSrc":"../../audio-sentences/t3-56-s04.mp3","clipSourceStart":21.85},{"id":"t3-56-u05","speaker":"M","text":"Camille, will the new pump arrive today?","start":23.22,"end":25.41,"clipSrc":"../../audio-sentences/t3-56-s05.mp3","clipSourceStart":23.14},{"id":"t3-56-u06","speaker":"W2","text":"Unfortunately, no. The manufacturer said there'll be a delay, and it won't arrive until Monday.","start":25.89,"end":31.5,"clipSrc":"../../audio-sentences/t3-56-meaning-06.mp3","clipSourceStart":25.81},{"id":"t3-56-u07","speaker":"W1","text":"I better let the customer know.","start":31.74,"end":33.48,"clipSrc":"../../audio-sentences/t3-56-s08.mp3","clipSourceStart":31.66},{"id":"t3-56-u08","speaker":"W1","text":"She was planning to fly the plane to Toronto this weekend for a friend's wedding.","start":33.81,"end":38.16,"clipSrc":"../../audio-sentences/t3-56-s09.mp3","clipSourceStart":33.73},{"id":"t3-56-u09","speaker":"W1","text":"She'll need to find another way to get there.","start":38.49,"end":40.53,"clipSrc":"../../audio-sentences/t3-56-s10.mp3","clipSourceStart":38.41}]},"t3-59":{"conversationId":"t3-59","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[17,18]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-59-u01","speaker":"M","text":"Hello, you've reached the customer service line for Quality Internet Service.","start":6,"end":10.35,"clipSrc":"../../audio-sentences/t3-59-s01.mp3","clipSourceStart":5.92},{"id":"t3-59-u02","speaker":"M","text":"How can I help you?","start":10.68,"end":11.61,"clipSrc":"../../audio-sentences/t3-59-s02.mp3","clipSourceStart":10.6},{"id":"t3-59-u03","speaker":"W","text":"I'm Mona Shannak, and my account number's PK62H5.","start":12.24,"end":17.290508,"clipSrc":"../../audio-sentences/t3-59-s03.mp3","clipSourceStart":12.16},{"id":"t3-59-u04","speaker":"W","text":"I'd like to close my account on June thirtieth.","start":18.3,"end":21.06,"clipSrc":"../../audio-sentences/t3-59-s04.mp3","clipSourceStart":18.22},{"id":"t3-59-u05","speaker":"M","text":"Oh, have you been experiencing issues with the service?","start":21.51,"end":24.48,"clipSrc":"../../audio-sentences/t3-59-s05.mp3","clipSourceStart":21.43},{"id":"t3-59-u06","speaker":"W","text":"Actually, my company has asked me to relocate to Spain.","start":24.84,"end":28.17,"clipSrc":"../../audio-sentences/t3-59-s06.mp3","clipSourceStart":24.76},{"id":"t3-59-u07","speaker":"M","text":"That's exciting! I'll take care of your request for you then.","start":28.68,"end":31.68,"clipSrc":"../../audio-sentences/t3-59-s07.mp3","clipSourceStart":28.6},{"id":"t3-59-u08","speaker":"W","text":"Thank you—I appreciate that.","start":32.01,"end":33.81,"clipSrc":"../../audio-sentences/t3-59-s08.mp3","clipSourceStart":31.93},{"id":"t3-59-u09","speaker":"M","text":"When I'm done updating your records, would you be willing to stay on the phone line to take a survey about your experience as a customer?","start":34.23,"end":40.62,"clipSrc":"../../audio-sentences/t3-59-s09.mp3","clipSourceStart":34.15},{"id":"t3-59-u10","speaker":"W","text":"Certainly.","start":40.98,"end":41.67,"clipSrc":"../../audio-sentences/t3-59-s10.mp3","clipSourceStart":40.9}]},"t3-62":{"conversationId":"t3-62","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[18,19]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-62-u01","speaker":"W","text":"Marco, you'll be restocking the cleaning products this morning, right? While you're doing that, could you also put the updated sale-price labels on the hand soap dispensers? They're on the shelf right above the laundry detergent.","start":7.35,"end":21,"clipSrc":"../../audio-sentences/t3-62-s01.mp3","clipSourceStart":7.27},{"id":"t3-62-u02","speaker":"M","text":"No problem—that shouldn't take long.","start":21.3,"end":23.43,"clipSrc":"../../audio-sentences/t3-62-s02.mp3","clipSourceStart":21.22},{"id":"t3-62-u03","speaker":"M","text":"What else can I help with?","start":23.7,"end":24.96,"clipSrc":"../../audio-sentences/t3-62-s03.mp3","clipSourceStart":23.62},{"id":"t3-62-u04","speaker":"W","text":"Can you make room for our new international foods section at the front of the store?","start":25.35,"end":29.88,"clipSrc":"../../audio-sentences/t3-62-s04.mp3","clipSourceStart":25.27},{"id":"t3-62-u05","speaker":"M","text":"Oh, did the shipment finally arrive? That snowstorm up north really affected delivery schedules.","start":30.15,"end":36.3,"clipSrc":"../../audio-sentences/t3-62-s05.mp3","clipSourceStart":30.07}]},"t3-65":{"conversationId":"t3-65","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[19,20]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-65-u01","speaker":"W","text":"Thanks for calling Kwon Photography Studio.","start":7.02,"end":9.33,"clipSrc":"../../audio-sentences/t3-65-s01.mp3","clipSourceStart":6.94},{"id":"t3-65-u02","speaker":"M","text":"Hello. I need to have a photo taken for a Canadian passport.","start":9.72,"end":13.08,"clipSrc":"../../audio-sentences/t3-65-meaning-02.mp3","clipSourceStart":9.64},{"id":"t3-65-u03","speaker":"W","text":"OK. You can make an appointment Monday through Friday.","start":13.59,"end":16.8,"clipSrc":"../../audio-sentences/t3-65-meaning-03.mp3","clipSourceStart":13.51},{"id":"t3-65-u04","speaker":"W","text":"Just bring in a copy of the application so we can see the size requirements.","start":17.31,"end":21.3,"clipSrc":"../../audio-sentences/t3-65-s06.mp3","clipSourceStart":17.23},{"id":"t3-65-u05","speaker":"M","text":"I work nine to five every day at my current job.","start":21.75,"end":24.24,"clipSrc":"../../audio-sentences/t3-65-s07.mp3","clipSourceStart":21.67},{"id":"t3-65-u06","speaker":"M","text":"Do you have any openings after five P.M.?","start":24.48,"end":26.61,"clipSrc":"../../audio-sentences/t3-65-s08.mp3","clipSourceStart":24.4},{"id":"t3-65-u07","speaker":"W","text":"No problem. We're open until six P.M. one day a week.","start":27,"end":30.6,"clipSrc":"../../audio-sentences/t3-65-meaning-07.mp3","clipSourceStart":26.92}]},"t3-68":{"conversationId":"t3-68","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 3 ets 2026.pdf","pages":[21,22]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t3-68-u01","speaker":"M","text":"Hi, Marina. Do you have receipts for your expenses from the dental hygienists' conference you attended last week?","start":6.45,"end":12.6,"clipSrc":"../../audio-sentences/t3-68-meaning-01.mp3","clipSourceStart":6.37},{"id":"t3-68-u02","speaker":"W","text":"Yes, I have them.","start":12.99,"end":14.37,"clipSrc":"../../audio-sentences/t3-68-s03.mp3","clipSourceStart":12.91},{"id":"t3-68-u03","speaker":"W","text":"I was just going to scan them and send them to you by e-mail.","start":14.58,"end":17.94,"clipSrc":"../../audio-sentences/t3-68-s04.mp3","clipSourceStart":14.5},{"id":"t3-68-u04","speaker":"M","text":"Thanks very much. Once I receive them, I'll process your request for reimbursement.","start":18.51,"end":23.31,"clipSrc":"../../audio-sentences/t3-68-meaning-04.mp3","clipSourceStart":18.43},{"id":"t3-68-u05","speaker":"M","text":"Don't forget to fill out the travel expenses form and include it in your e-mail, too.","start":23.94,"end":27.72,"clipSrc":"../../audio-sentences/t3-68-s07.mp3","clipSourceStart":23.86},{"id":"t3-68-u06","speaker":"W","text":"OK. Remind me, what should I use for the department code?","start":28.41,"end":33.12,"clipSrc":"../../audio-sentences/t3-68-meaning-06.mp3","clipSourceStart":28.33},{"id":"t3-68-u07","speaker":"M","text":"Oh, sorry. I forgot to tell you.","start":33.48,"end":35.19,"clipSrc":"../../audio-sentences/t3-68-meaning-07.mp3","clipSourceStart":33.4},{"id":"t3-68-u08","speaker":"M","text":"Use number 1009.","start":35.49,"end":36.27,"clipSrc":"../../audio-sentences/t3-68-s12.mp3","clipSourceStart":35.41}]},"t4-32":{"conversationId":"t4-32","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[8]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-32-u01","speaker":"W","text":"Good morning. Thanks for coming to tour this apartment building.","start":5.94,"end":9.54,"clipSrc":"../../audio-sentences/t4-32-meaning-01.mp3","clipSourceStart":5.86},{"id":"t4-32-u02","speaker":"M","text":"I'm glad I could visit in person.","start":9.93,"end":11.7,"clipSrc":"../../audio-sentences/t4-32-s03.mp3","clipSourceStart":9.85},{"id":"t4-32-u03","speaker":"M","text":"I've always wanted to live in this neighborhood—it's so beautiful.","start":12.03,"end":15.42,"clipSrc":"../../audio-sentences/t4-32-s04.mp3","clipSourceStart":11.95},{"id":"t4-32-u04","speaker":"M","text":"This building is brand-new, isn't it?","start":15.93,"end":17.94,"clipSrc":"../../audio-sentences/t4-32-s05.mp3","clipSourceStart":15.85},{"id":"t4-32-u05","speaker":"W","text":"Yes. In fact, you'd be among the very first tenants if you decide to move here.","start":18.27,"end":23.46,"clipSrc":"../../audio-sentences/t4-32-meaning-05.mp3","clipSourceStart":18.19},{"id":"t4-32-u06","speaker":"W","text":"Before you look at some apartments, would you please sign your name here in our guest book?","start":23.91,"end":28.47,"clipSrc":"../../audio-sentences/t4-32-s08.mp3","clipSourceStart":23.83},{"id":"t4-32-u07","speaker":"M","text":"Oh, of course..","start":28.77,"end":29.76,"clipSrc":"../../audio-sentences/t4-32-s09.mp3","clipSourceStart":28.69}]},"t4-35":{"conversationId":"t4-35","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[9]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-35-u01","speaker":"W","text":"Chen, I hope all is going well on your first day.","start":6.09,"end":9.6,"clipSrc":"../../audio-sentences/t4-35-s01.mp3","clipSourceStart":6.01},{"id":"t4-35-u02","speaker":"W","text":"I saw you have some scheduled seafood deliveries across the bay in the Morgan District.","start":9.9,"end":14.76,"clipSrc":"../../audio-sentences/t4-35-s02.mp3","clipSourceStart":9.82},{"id":"t4-35-u03","speaker":"W","text":"Why haven't you left yet?","start":15.09,"end":16.62,"clipSrc":"../../audio-sentences/t4-35-s03.mp3","clipSourceStart":15.01},{"id":"t4-35-u04","speaker":"M","text":"I wasn't going to head over to that particular area for another hour.","start":16.92,"end":20.43,"clipSrc":"../../audio-sentences/t4-35-s04.mp3","clipSourceStart":16.84},{"id":"t4-35-u05","speaker":"M","text":"Do the restaurants in the Morgan District want their deliveries earlier than scheduled?","start":20.91,"end":24.93,"clipSrc":"../../audio-sentences/t4-35-s05.mp3","clipSourceStart":20.83},{"id":"t4-35-u06","speaker":"W","text":"No, but I'm concerned about Bay Bridge traffic.","start":25.29,"end":28.74,"clipSrc":"../../audio-sentences/t4-35-s06.mp3","clipSourceStart":25.21},{"id":"t4-35-u07","speaker":"W","text":"It's routinely congested with vehicles.","start":28.98,"end":31.38,"clipSrc":"../../audio-sentences/t4-35-s07.mp3","clipSourceStart":28.9},{"id":"t4-35-u08","speaker":"W","text":"So you should always add at least an extra hour to your trip out there.","start":31.62,"end":35.82,"clipSrc":"../../audio-sentences/t4-35-s08.mp3","clipSourceStart":31.54},{"id":"t4-35-u09","speaker":"M","text":"Thanks for the tip.","start":36.06,"end":37.02,"clipSrc":"../../audio-sentences/t4-35-s09.mp3","clipSourceStart":35.98},{"id":"t4-35-u10","speaker":"M","text":"I'll also check traffic Webcams on the highway agency's Web site.","start":37.47,"end":41.22,"clipSrc":"../../audio-sentences/t4-35-s10.mp3","clipSourceStart":37.39}]},"t4-38":{"conversationId":"t4-38","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[10,11]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-38-u01","speaker":"M","text":"This morning I got an e-mail from Pelicon, a local producer of beauty products.","start":5.52,"end":10.53,"clipSrc":"../../audio-sentences/t4-38-s01.mp3","clipSourceStart":5.44},{"id":"t4-38-u02","speaker":"M","text":"They're interested in purchasing lanolin from us to use in their new line of all-natural makeup.","start":11.04,"end":16.23,"clipSrc":"../../audio-sentences/t4-38-s02.mp3","clipSourceStart":10.96},{"id":"t4-38-u03","speaker":"W","text":"I'm not sure about that.","start":16.77,"end":18.39,"clipSrc":"../../audio-sentences/t4-38-s03.mp3","clipSourceStart":16.69},{"id":"t4-38-u04","speaker":"W","text":"We're a fairly small farm, and we already sell lanolin to another local business.","start":18.66,"end":22.95,"clipSrc":"../../audio-sentences/t4-38-s04.mp3","clipSourceStart":18.58},{"id":"t4-38-u05","speaker":"W","text":"I'm worried that we don't produce enough lanolin to meet the demand of another client.","start":23.34,"end":27.51,"clipSrc":"../../audio-sentences/t4-38-s05.mp3","clipSourceStart":23.26},{"id":"t4-38-u06","speaker":"W","text":"I don't want to expand and take on more wool production.","start":28.02,"end":30.72,"clipSrc":"../../audio-sentences/t4-38-s06.mp3","clipSourceStart":27.94},{"id":"t4-38-u07","speaker":"M","text":"But our contract with the business we currently supply lanolin to has almost expired—there's no guarantee it will be renewed.","start":31.26,"end":39.12,"clipSrc":"../../audio-sentences/t4-38-s07.mp3","clipSourceStart":31.18},{"id":"t4-38-u08","speaker":"M","text":"I think you should at least read Pelicon's proposal.","start":39.54,"end":42.57,"clipSrc":"../../audio-sentences/t4-38-s08.mp3","clipSourceStart":39.46},{"id":"t4-38-u09","speaker":"W","text":"Sure. Can you forward me the e-mail?","start":42.87,"end":45.06,"clipSrc":"../../audio-sentences/t4-38-meaning-09.mp3","clipSourceStart":42.79}]},"t4-41":{"conversationId":"t4-41","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[11,12]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-41-u01","speaker":"M","text":"Nisreen? This is Lewis.","start":5.88,"end":7.77,"clipSrc":"../../audio-sentences/t4-41-s01.mp3","clipSourceStart":5.8},{"id":"t4-41-u02","speaker":"M","text":"I heard you're going to be working for our company overseas, in the New Zealand office.","start":8.25,"end":12.75,"clipSrc":"../../audio-sentences/t4-41-s02.mp3","clipSourceStart":8.17},{"id":"t4-41-u03","speaker":"M","text":"What a great opportunity!","start":12.96,"end":14.55,"clipSrc":"../../audio-sentences/t4-41-s03.mp3","clipSourceStart":12.88},{"id":"t4-41-u04","speaker":"W","text":"Yes, thank you. I start next month, and I'm really excited.","start":14.88,"end":19.56,"clipSrc":"../../audio-sentences/t4-41-meaning-04.mp3","clipSourceStart":14.8},{"id":"t4-41-u05","speaker":"M","text":"I'm calling to touch base with you about some of our vendor contracts.","start":20.07,"end":23.73,"clipSrc":"../../audio-sentences/t4-41-s06.mp3","clipSourceStart":19.99},{"id":"t4-41-u06","speaker":"M","text":"It's time to renew the contracts, and I wanted to ask you to take care of that before you left.","start":24.09,"end":29.34,"clipSrc":"../../audio-sentences/t4-41-s07.mp3","clipSourceStart":24.01},{"id":"t4-41-u07","speaker":"W","text":"No problem. I know where those files are located on our shared computer drive.","start":29.61,"end":34.41,"clipSrc":"../../audio-sentences/t4-41-meaning-07.mp3","clipSourceStart":29.53},{"id":"t4-41-u08","speaker":"W","text":"I'll just need the password to access them.","start":34.77,"end":37.11,"clipSrc":"../../audio-sentences/t4-41-s10.mp3","clipSourceStart":34.69}]},"t4-44":{"conversationId":"t4-44","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[12,13]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-44-u01","speaker":"W","text":"Hi. This is Giovanni Marino's agent. I'm calling to reschedule his planned appearance on the Sunday Morning Show.","start":6.12,"end":12.9,"clipSrc":"../../audio-sentences/t4-44-meaning-01.mp3","clipSourceStart":6.04},{"id":"t4-44-u02","speaker":"M","text":"Right. We have him booked to appear on the show in July to promote his new movie.","start":13.2,"end":18.06,"clipSrc":"../../audio-sentences/t4-44-meaning-02.mp3","clipSourceStart":13.12},{"id":"t4-44-u03","speaker":"W","text":"Unfortunately, the movie he's acting in is behind schedule, and he'll now be on location through the end of August.","start":18.39,"end":24.78,"clipSrc":"../../audio-sentences/t4-44-s06.mp3","clipSourceStart":18.31},{"id":"t4-44-u04","speaker":"M","text":"Hmm, I see. Let me look at our guest calendar.","start":25.2,"end":28.65,"clipSrc":"../../audio-sentences/t4-44-meaning-04.mp3","clipSourceStart":25.12},{"id":"t4-44-u05","speaker":"M","text":"I have a slot I'm looking to fill on September fourteenth—would that work?","start":29.4,"end":34.26,"clipSrc":"../../audio-sentences/t4-44-s09.mp3","clipSourceStart":29.32},{"id":"t4-44-u06","speaker":"W","text":"Yes, that would be great, thanks.","start":34.59,"end":37.02,"clipSrc":"../../audio-sentences/t4-44-s10.mp3","clipSourceStart":34.51},{"id":"t4-44-u07","speaker":"M","text":"All right. I'll update the contract with the new date and e-mail it to you.","start":37.23,"end":41.43,"clipSrc":"../../audio-sentences/t4-44-meaning-07.mp3","clipSourceStart":37.15}]},"t4-47":{"conversationId":"t4-47","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[13,14]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-47-u01","speaker":"M1","text":"Hello, Usha. Hi, Pablo.","start":7.32,"end":9.18,"clipSrc":"../../audio-sentences/t4-47-meaning-01.mp3","clipSourceStart":7.24},{"id":"t4-47-u02","speaker":"W","text":"Hey, Konstantin. We're talking about our thoughts on the new company policy for remote workers.","start":9.6,"end":15.12,"clipSrc":"../../audio-sentences/t4-47-meaning-02.mp3","clipSourceStart":9.52},{"id":"t4-47-u03","speaker":"W","text":"On the days I have to come into the office, I always worry about finding an appropriate workstation.","start":15.63,"end":20.58,"clipSrc":"../../audio-sentences/t4-47-s05.mp3","clipSourceStart":15.55},{"id":"t4-47-u04","speaker":"M2","text":"Yeah, I don't like the unpredictability either.","start":21.15,"end":24.09,"clipSrc":"../../audio-sentences/t4-47-s06.mp3","clipSourceStart":21.07},{"id":"t4-47-u05","speaker":"M2","text":"Why can't we just sign up for our workstation sometime in advance? What do you think about it?","start":24.39,"end":29.55,"clipSrc":"../../audio-sentences/t4-47-s07.mp3","clipSourceStart":24.31},{"id":"t4-47-u06","speaker":"M1","text":"These are good points.","start":30,"end":31.29,"clipSrc":"../../audio-sentences/t4-47-s08.mp3","clipSourceStart":29.92},{"id":"t4-47-u07","speaker":"M1","text":"Let's all go to the director to discuss this with her.","start":31.59,"end":34.38,"clipSrc":"../../audio-sentences/t4-47-s09.mp3","clipSourceStart":31.51},{"id":"t4-47-u08","speaker":"M2","text":"I believe she's in her office, so now's a good time.","start":34.89,"end":37.62,"clipSrc":"../../audio-sentences/t4-47-s10.mp3","clipSourceStart":34.81},{"id":"t4-47-u09","speaker":"W","text":"Oh, I can't go now.","start":37.92,"end":39.39,"clipSrc":"../../audio-sentences/t4-47-s11.mp3","clipSourceStart":37.84},{"id":"t4-47-u10","speaker":"W","text":"I have a report to finalize by noon.","start":39.69,"end":41.64,"clipSrc":"../../audio-sentences/t4-47-s12.mp3","clipSourceStart":39.61}]},"t4-50":{"conversationId":"t4-50","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[14,15]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-50-u01","speaker":"W","text":"OK, Mr. Jebreen. Here's your new library card.","start":5.88,"end":8.94,"clipSrc":"../../audio-sentences/t4-50-meaning-01.mp3","clipSourceStart":5.8},{"id":"t4-50-u02","speaker":"W","text":"Remember that you can borrow books, CDs, and DVDs from our collection with it.","start":9.39,"end":13.74,"clipSrc":"../../audio-sentences/t4-50-s03.mp3","clipSourceStart":9.31},{"id":"t4-50-u03","speaker":"M","text":"Thank you. I read somewhere that people can also borrow digital items.","start":14.04,"end":18.48,"clipSrc":"../../audio-sentences/t4-50-meaning-03.mp3","clipSourceStart":13.96},{"id":"t4-50-u04","speaker":"W","text":"Yes! We offer the Cloud-Camel application.","start":18.84,"end":21.93,"clipSrc":"../../audio-sentences/t4-50-s06.mp3","clipSourceStart":18.76},{"id":"t4-50-u05","speaker":"W","text":"All you have to do is download the app and use the information on your card to set up an account.","start":22.41,"end":27.06,"clipSrc":"../../audio-sentences/t4-50-s07.mp3","clipSourceStart":22.33},{"id":"t4-50-u06","speaker":"M","text":"That's great. I go on a business trip every month, so having easy access to online content will be convenient.","start":27.3,"end":34.62,"clipSrc":"../../audio-sentences/t4-50-meaning-06.mp3","clipSourceStart":27.22}]},"t4-53":{"conversationId":"t4-53","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[15,16]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-53-u01","speaker":"W","text":"Have you reviewed the data from the workplace survey? You really should.","start":5.97,"end":10.17,"clipSrc":"../../audio-sentences/t4-53-s01.mp3","clipSourceStart":5.89},{"id":"t4-53-u02","speaker":"W","text":"It looks like most staff feel positive about the direction that the company is going in.","start":10.47,"end":15.18,"clipSrc":"../../audio-sentences/t4-53-s02.mp3","clipSourceStart":10.39},{"id":"t4-53-u03","speaker":"W","text":"But almost 40 percent feel like their individual contributions aren't being recognized.","start":15.66,"end":21.93,"clipSrc":"../../audio-sentences/t4-53-s03.mp3","clipSourceStart":15.58},{"id":"t4-53-u04","speaker":"M","text":"Well, the company's certainly had other priorities.","start":22.41,"end":25.65,"clipSrc":"../../audio-sentences/t4-53-s04.mp3","clipSourceStart":22.33},{"id":"t4-53-u05","speaker":"M","text":"I wonder how the management team's going to respond.","start":26.25,"end":28.71,"clipSrc":"../../audio-sentences/t4-53-s05.mp3","clipSourceStart":26.17},{"id":"t4-53-u06","speaker":"W","text":"I've suggested many times that they give out awards every quarter for exceptional performance.","start":29.1,"end":34.8,"clipSrc":"../../audio-sentences/t4-53-s06.mp3","clipSourceStart":29.02},{"id":"t4-53-u07","speaker":"W","text":"Maybe now they'll finally start doing it.","start":35.16,"end":37.23,"clipSrc":"../../audio-sentences/t4-53-s07.mp3","clipSourceStart":35.08}]},"t4-56":{"conversationId":"t4-56","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[16,17]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-56-u01","speaker":"W1","text":"Hi, Ajijola. As I mentioned on the phone, my colleague and I recently started a clothing company and are hoping your branding firm can help us promote our line of athletic apparel.","start":7.17,"end":18.51,"clipSrc":"../../audio-sentences/t4-56-meaning-01.mp3","clipSourceStart":7.09},{"id":"t4-56-u02","speaker":"W1","text":"You think we should focus on advertising on social media, right?","start":19.05,"end":23.52,"clipSrc":"../../audio-sentences/t4-56-s03.mp3","clipSourceStart":18.97},{"id":"t4-56-u03","speaker":"M","text":"Right. Contrary to popular belief, television is definitely not the entire advertising landscape.","start":24.06,"end":30.6,"clipSrc":"../../audio-sentences/t4-56-meaning-03.mp3","clipSourceStart":23.98},{"id":"t4-56-u04","speaker":"M","text":"Advertising on the Internet is also a great way for a company to increase its visibility.","start":31.11,"end":36.3,"clipSrc":"../../audio-sentences/t4-56-s06.mp3","clipSourceStart":31.03},{"id":"t4-56-u05","speaker":"W2","text":"I heard you recommended working with an online influencer.","start":36.63,"end":39.81,"clipSrc":"../../audio-sentences/t4-56-s07.mp3","clipSourceStart":36.55},{"id":"t4-56-u06","speaker":"M","text":"Yes—Saskia Hoffman. Saskia's very knowledgeable about exercise, and lots of people use her online exercise routines.","start":40.11,"end":48.93,"clipSrc":"../../audio-sentences/t4-56-meaning-06.mp3","clipSourceStart":40.03},{"id":"t4-56-u07","speaker":"M","text":"Her viewers will pay attention to what she recommends and wears.","start":49.5,"end":52.65,"clipSrc":"../../audio-sentences/t4-56-s10.mp3","clipSourceStart":49.42}]},"t4-59":{"conversationId":"t4-59","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[17,18]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-59-u01","speaker":"W","text":"Hi, Shinji. I wanted to ask you about the order we got from the department store chain.","start":6.03,"end":10.83,"clipSrc":"../../audio-sentences/t4-59-meaning-01.mp3","clipSourceStart":5.95},{"id":"t4-59-u02","speaker":"W","text":"You know, the one that placed an order for 5,000 jigsaw puzzles?","start":11.13,"end":14.46,"clipSrc":"../../audio-sentences/t4-59-s03.mp3","clipSourceStart":11.05},{"id":"t4-59-u03","speaker":"M","text":"Yes. They want the order in a week so they can stock them before the holiday.","start":14.82,"end":19.56,"clipSrc":"../../audio-sentences/t4-59-meaning-03.mp3","clipSourceStart":14.74},{"id":"t4-59-u04","speaker":"W","text":"A week is not a long time.","start":19.98,"end":22.02,"clipSrc":"../../audio-sentences/t4-59-s06.mp3","clipSourceStart":19.9},{"id":"t4-59-u05","speaker":"M","text":"We've had short timelines before.","start":22.59,"end":24.48,"clipSrc":"../../audio-sentences/t4-59-s07.mp3","clipSourceStart":22.51},{"id":"t4-59-u06","speaker":"M","text":"Anyway, our illustrators sent some new puzzle illustrations, right? I heard they're making a special edition.","start":24.72,"end":30.99,"clipSrc":"../../audio-sentences/t4-59-s08.mp3","clipSourceStart":24.64},{"id":"t4-59-u07","speaker":"W","text":"Yes, and I'm so excited! I've got the sketches right here.","start":31.23,"end":34.86,"clipSrc":"../../audio-sentences/t4-59-s09.mp3","clipSourceStart":31.15},{"id":"t4-59-u08","speaker":"W","text":"Let me show you.","start":35.01,"end":35.85,"clipSrc":"../../audio-sentences/t4-59-s10.mp3","clipSourceStart":34.93}]},"t4-62":{"conversationId":"t4-62","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[18,19]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-62-u01","speaker":"M","text":"Hi, Ms. Rossi. I understand you're concerned about a charge that appears on the statement for your business account.","start":7.38,"end":13.95,"clipSrc":"../../audio-sentences/t4-62-meaning-01.mp3","clipSourceStart":7.3},{"id":"t4-62-u02","speaker":"W","text":"Yes, I have a question about the charge on May 3.","start":14.46,"end":17.34,"clipSrc":"../../audio-sentences/t4-62-s03.mp3","clipSourceStart":14.38},{"id":"t4-62-u03","speaker":"W","text":"I don't remember purchasing anything for that amount.","start":18.3,"end":21.24,"clipSrc":"../../audio-sentences/t4-62-s04.mp3","clipSourceStart":18.22},{"id":"t4-62-u04","speaker":"M","text":"Let me review your statement now.","start":21.75,"end":23.73,"clipSrc":"../../audio-sentences/t4-62-s05.mp3","clipSourceStart":21.67},{"id":"t4-62-u05","speaker":"M","text":"Hmm. It looks like that purchase was made abroad.","start":24.21,"end":28.14,"clipSrc":"../../audio-sentences/t4-62-meaning-05.mp3","clipSourceStart":24.13},{"id":"t4-62-u06","speaker":"M","text":"So an international transaction fee was added to the purchase amount.","start":28.35,"end":32.13,"clipSrc":"../../audio-sentences/t4-62-s08.mp3","clipSourceStart":28.27},{"id":"t4-62-u07","speaker":"W","text":"Oh, yes—I was out of the country at that time.","start":32.49,"end":36.24,"clipSrc":"../../audio-sentences/t4-62-s09.mp3","clipSourceStart":32.41},{"id":"t4-62-u08","speaker":"W","text":"Thanks for clarifying. Can you provide me with a list of all the bank fees for transactions made abroad?","start":36.48,"end":42.78,"clipSrc":"../../audio-sentences/t4-62-meaning-08.mp3","clipSourceStart":36.4},{"id":"t4-62-u09","speaker":"M","text":"Yes, of course. Here's a document that lists all the information.","start":43.05,"end":47.25,"clipSrc":"../../audio-sentences/t4-62-meaning-09.mp3","clipSourceStart":42.97}]},"t4-65":{"conversationId":"t4-65","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[20,21]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-65-u01","speaker":"M","text":"Magali, were you able to reserve the performing arts center for the piano concert?","start":6.75,"end":11.19,"clipSrc":"../../audio-sentences/t4-65-s01.mp3","clipSourceStart":6.67},{"id":"t4-65-u02","speaker":"W","text":"Yes. I booked their main auditorium for that day.","start":11.37,"end":14.64,"clipSrc":"../../audio-sentences/t4-65-meaning-02.mp3","clipSourceStart":11.29},{"id":"t4-65-u03","speaker":"W","text":"They're sending me the contract.","start":14.97,"end":16.47,"clipSrc":"../../audio-sentences/t4-65-s04.mp3","clipSourceStart":14.89},{"id":"t4-65-u04","speaker":"M","text":"Thanks for doing that.","start":16.83,"end":18,"clipSrc":"../../audio-sentences/t4-65-s05.mp3","clipSourceStart":16.75},{"id":"t4-65-u05","speaker":"W","text":"No problem. Hopefully, it'll be as successful as last year.","start":18.09,"end":21.9,"clipSrc":"../../audio-sentences/t4-65-meaning-05.mp3","clipSourceStart":18.01},{"id":"t4-65-u06","speaker":"M","text":"We sold 2,000 tickets last year, but we had three celebrity performers.","start":22.35,"end":27.39,"clipSrc":"../../audio-sentences/t4-65-s08.mp3","clipSourceStart":22.27},{"id":"t4-65-u07","speaker":"M","text":"I'm worried we won't sell as many tickets this year.","start":27.69,"end":30.3,"clipSrc":"../../audio-sentences/t4-65-s09.mp3","clipSourceStart":27.61},{"id":"t4-65-u08","speaker":"W","text":"Well, Xinyu Gu is a very popular pianist.","start":30.6,"end":33.84,"clipSrc":"../../audio-sentences/t4-65-s10.mp3","clipSourceStart":30.52},{"id":"t4-65-u09","speaker":"W","text":"And she's staying after the concert to sign autographs.","start":34.08,"end":37.23,"clipSrc":"../../audio-sentences/t4-65-s11.mp3","clipSourceStart":34},{"id":"t4-65-u10","speaker":"W","text":"Which reminds me, where should we set up the table for that?","start":37.77,"end":41.13,"clipSrc":"../../audio-sentences/t4-65-s12.mp3","clipSourceStart":37.69},{"id":"t4-65-u11","speaker":"M","text":"Good question. Hmm. The café should be closed by then.","start":41.25,"end":45.69,"clipSrc":"../../audio-sentences/t4-65-meaning-11.mp3","clipSourceStart":41.17},{"id":"t4-65-u12","speaker":"M","text":"Let's set it up next to the café.","start":46.08,"end":47.64,"clipSrc":"../../audio-sentences/t4-65-s16.mp3","clipSourceStart":46}]},"t4-68":{"conversationId":"t4-68","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 4 ets 2026.pdf","pages":[21,22]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t4-68-u01","speaker":"M","text":"Welcome to the garden center.","start":7.11,"end":8.52,"clipSrc":"../../audio-sentences/t4-68-s01.mp3","clipSourceStart":7.03},{"id":"t4-68-u02","speaker":"M","text":"Can I help you?","start":8.7,"end":9.42,"clipSrc":"../../audio-sentences/t4-68-s02.mp3","clipSourceStart":8.62},{"id":"t4-68-u03","speaker":"W","text":"Hi. I've started growing rose bushes, and I've heard they require special care.","start":9.66,"end":14.46,"clipSrc":"../../audio-sentences/t4-68-meaning-03.mp3","clipSourceStart":9.58},{"id":"t4-68-u04","speaker":"W","text":"Are there any products you can recommend?","start":14.76,"end":16.62,"clipSrc":"../../audio-sentences/t4-68-s05.mp3","clipSourceStart":14.68},{"id":"t4-68-u05","speaker":"M","text":"Yes! But first, I'd like to show you a great resource on our Web site.","start":16.89,"end":21.42,"clipSrc":"../../audio-sentences/t4-68-s06.mp3","clipSourceStart":16.81},{"id":"t4-68-u06","speaker":"M","text":"Have you seen our blog?","start":21.66,"end":22.98,"clipSrc":"../../audio-sentences/t4-68-s07.mp3","clipSourceStart":21.58},{"id":"t4-68-u07","speaker":"W","text":"No, I haven't.","start":23.13,"end":24.21,"clipSrc":"../../audio-sentences/t4-68-s08.mp3","clipSourceStart":23.05},{"id":"t4-68-u08","speaker":"M","text":"We have monthly posts on many gardening topics, and there's a recent one about growing roses.","start":24.48,"end":30.15,"clipSrc":"../../audio-sentences/t4-68-s09.mp3","clipSourceStart":24.4},{"id":"t4-68-u09","speaker":"W","text":"I'll check it out! Thanks so much.","start":30.39,"end":32.58,"clipSrc":"../../audio-sentences/t4-68-s10.mp3","clipSourceStart":30.31},{"id":"t4-68-u10","speaker":"M","text":"You're welcome. Now— let me show you our fertilizers.","start":32.67,"end":36.18,"clipSrc":"../../audio-sentences/t4-68-meaning-10.mp3","clipSourceStart":32.59},{"id":"t4-68-u11","speaker":"M","text":"They're in aisle six.","start":36.3,"end":37.8,"clipSrc":"../../audio-sentences/t4-68-s13.mp3","clipSourceStart":36.22}]},"t5-32":{"conversationId":"t5-32","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[7,8]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-32-u01","speaker":"W","text":"Hello, Tariq. Could you do me a favor?","start":6.03,"end":8.37,"clipSrc":"../../audio-sentences/t5-32-meaning-01.mp3","clipSourceStart":5.95},{"id":"t5-32-u02","speaker":"M","text":"Sure—what is it?","start":8.76,"end":10.05,"clipSrc":"../../audio-sentences/t5-32-s03.mp3","clipSourceStart":8.68},{"id":"t5-32-u03","speaker":"W","text":"I'm meeting with the Gerhard Group at ten A.M. for the product pitch, and I need copies of your market analysis report made for each representative.","start":10.47,"end":19.26,"clipSrc":"../../audio-sentences/t5-32-s04.mp3","clipSourceStart":10.39},{"id":"t5-32-u04","speaker":"M","text":"Aren't you at the office right now?","start":19.68,"end":21.63,"clipSrc":"../../audio-sentences/t5-32-s05.mp3","clipSourceStart":19.6},{"id":"t5-32-u05","speaker":"W","text":"Actually, I came in early today, but I couldn't get the copy machine to work.","start":22.08,"end":26.67,"clipSrc":"../../audio-sentences/t5-32-s06.mp3","clipSourceStart":22},{"id":"t5-32-u06","speaker":"M","text":"Seriously? We bought it last month!","start":27,"end":29.7,"clipSrc":"../../audio-sentences/t5-32-s07.mp3","clipSourceStart":26.92},{"id":"t5-32-u07","speaker":"W","text":"I'm afraid so.","start":30.24,"end":31.26,"clipSrc":"../../audio-sentences/t5-32-s08.mp3","clipSourceStart":30.16},{"id":"t5-32-u08","speaker":"M","text":"I just got off the train.","start":31.74,"end":33.18,"clipSrc":"../../audio-sentences/t5-32-s09.mp3","clipSourceStart":31.66},{"id":"t5-32-u09","speaker":"M","text":"I'll stop at Business Express on McAllister Street and take care of it on my way to the office.","start":33.3,"end":38.1,"clipSrc":"../../audio-sentences/t5-32-s10.mp3","clipSourceStart":33.22}]},"t5-35":{"conversationId":"t5-35","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[8,9]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-35-u01","speaker":"W","text":"Delton Van Lines. How can I help you?","start":6.06,"end":8.55,"clipSrc":"../../audio-sentences/t5-35-meaning-01.mp3","clipSourceStart":5.98},{"id":"t5-35-u02","speaker":"M","text":"Hello. I'm the office manager at Woodsom Insurance Company.","start":8.97,"end":12.33,"clipSrc":"../../audio-sentences/t5-35-meaning-02.mp3","clipSourceStart":8.89},{"id":"t5-35-u03","speaker":"M","text":"We are relocating to a new office in June and would like to book your services.","start":12.66,"end":17.01,"clipSrc":"../../audio-sentences/t5-35-s05.mp3","clipSourceStart":12.58},{"id":"t5-35-u04","speaker":"W","text":"Certainly! But before we reserve a date for the move, we'll need to come to your current location and estimate the cost of moving your furniture and equipment.","start":17.46,"end":26.16,"clipSrc":"../../audio-sentences/t5-35-s06.mp3","clipSourceStart":17.38},{"id":"t5-35-u05","speaker":"M","text":"We have a staff meeting tomorrow morning, so no one's available to show you around then.","start":26.67,"end":31.68,"clipSrc":"../../audio-sentences/t5-35-s07.mp3","clipSourceStart":26.59},{"id":"t5-35-u06","speaker":"M","text":"But tomorrow afternoon works.","start":32.1,"end":33.84,"clipSrc":"../../audio-sentences/t5-35-s08.mp3","clipSourceStart":32.02},{"id":"t5-35-u07","speaker":"W","text":"Perfect! Our representative can be there at two.","start":34.23,"end":37.11,"clipSrc":"../../audio-sentences/t5-35-s09.mp3","clipSourceStart":34.15},{"id":"t5-35-u08","speaker":"W","text":"I'll just need to know where you're located.","start":37.53,"end":39.48,"clipSrc":"../../audio-sentences/t5-35-s10.mp3","clipSourceStart":37.45}]},"t5-38":{"conversationId":"t5-38","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[9,10]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-38-u01","speaker":"M","text":"Doctor MacMillan, I'm calling from the human resources department.","start":5.52,"end":9.66,"clipSrc":"../../audio-sentences/t5-38-s01.mp3","clipSourceStart":5.44},{"id":"t5-38-u02","speaker":"M","text":"I'm in charge of your onboarding, and I wanted to confirm your start date.","start":10.08,"end":14.4,"clipSrc":"../../audio-sentences/t5-38-s02.mp3","clipSourceStart":10},{"id":"t5-38-u03","speaker":"M","text":"It's the first of April, right?","start":14.88,"end":16.56,"clipSrc":"../../audio-sentences/t5-38-s03.mp3","clipSourceStart":14.8},{"id":"t5-38-u04","speaker":"W","text":"Right. That's when I'll be joining the scientific research team.","start":16.83,"end":20.19,"clipSrc":"../../audio-sentences/t5-38-meaning-04.mp3","clipSourceStart":16.75},{"id":"t5-38-u05","speaker":"W","text":"And as you probably know, I'm still finishing up a research paper with my current institution.","start":20.7,"end":26.37,"clipSrc":"../../audio-sentences/t5-38-s06.mp3","clipSourceStart":20.62},{"id":"t5-38-u06","speaker":"M","text":"Yes, the director did tell me that.","start":26.67,"end":28.98,"clipSrc":"../../audio-sentences/t5-38-s07.mp3","clipSourceStart":26.59},{"id":"t5-38-u07","speaker":"M","text":"Your contract includes time for you to finish up your previous commitments.","start":29.4,"end":33.39,"clipSrc":"../../audio-sentences/t5-38-s08.mp3","clipSourceStart":29.32},{"id":"t5-38-u08","speaker":"M","text":"I can send it to you this afternoon.","start":33.78,"end":35.67,"clipSrc":"../../audio-sentences/t5-38-s09.mp3","clipSourceStart":33.7}]},"t5-41":{"conversationId":"t5-41","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[10,11]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-41-u01","speaker":"W1","text":"We've been getting a lot of online orders for our chocolate candies lately.","start":7.08,"end":10.89,"clipSrc":"../../audio-sentences/t5-41-s01.mp3","clipSourceStart":7},{"id":"t5-41-u02","speaker":"W1","text":"I'm glad to see the increase in orders, but I'm worried about meeting the demands.","start":11.37,"end":15.78,"clipSrc":"../../audio-sentences/t5-41-s02.mp3","clipSourceStart":11.29},{"id":"t5-41-u03","speaker":"W1","text":"Are we going to be able to fill and ship all these orders?","start":16.29,"end":19.26,"clipSrc":"../../audio-sentences/t5-41-s03.mp3","clipSourceStart":16.21},{"id":"t5-41-u04","speaker":"M","text":"I think we should hire a few more people to work in the mornings.","start":19.71,"end":22.86,"clipSrc":"../../audio-sentences/t5-41-s04.mp3","clipSourceStart":19.63},{"id":"t5-41-u05","speaker":"M","text":"They could help with packaging and shipping.","start":23.19,"end":25.11,"clipSrc":"../../audio-sentences/t5-41-s05.mp3","clipSourceStart":23.11},{"id":"t5-41-u06","speaker":"M","text":"What do you think, Rebecca?","start":25.47,"end":26.82,"clipSrc":"../../audio-sentences/t5-41-s06.mp3","clipSourceStart":25.39},{"id":"t5-41-u07","speaker":"W2","text":"I agree. I also think that we should ask if our delivery service can pick up our packages twice a day instead of just once a day—maybe every morning and afternoon.","start":27.33,"end":39.03,"clipSrc":"../../audio-sentences/t5-41-meaning-07.mp3","clipSourceStart":27.25},{"id":"t5-41-u08","speaker":"W2","text":"I'll call them today.","start":39.42,"end":40.65,"clipSrc":"../../audio-sentences/t5-41-s09.mp3","clipSourceStart":39.34}]},"t5-44":{"conversationId":"t5-44","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[11,12]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-44-u01","speaker":"W","text":"I spoke to the Mancini brothers.","start":6.06,"end":7.8,"clipSrc":"../../audio-sentences/t5-44-s01.mp3","clipSourceStart":5.98},{"id":"t5-44-u02","speaker":"W","text":"They just shipped our leather order—the hazelnut color.","start":8.07,"end":11.25,"clipSrc":"../../audio-sentences/t5-44-s02.mp3","clipSourceStart":7.99},{"id":"t5-44-u03","speaker":"W","text":"But it'll take a while to arrive.","start":11.52,"end":13.38,"clipSrc":"../../audio-sentences/t5-44-s03.mp3","clipSourceStart":11.44},{"id":"t5-44-u04","speaker":"W","text":"We don't have enough in stock to complete the ten sofa orders that we've received the past few days.","start":13.8,"end":19.77,"clipSrc":"../../audio-sentences/t5-44-s04.mp3","clipSourceStart":13.72},{"id":"t5-44-u05","speaker":"M","text":"What about the local leather supplier that brought us some samples last week? We could ask them whether they have enough for ten sofas.","start":20.16,"end":27.24,"clipSrc":"../../audio-sentences/t5-44-s05.mp3","clipSourceStart":20.08},{"id":"t5-44-u06","speaker":"W","text":"To be honest, I wasn't very impressed with the quality of their leather.","start":27.63,"end":31.29,"clipSrc":"../../audio-sentences/t5-44-s06.mp3","clipSourceStart":27.55},{"id":"t5-44-u07","speaker":"W","text":"I'd rather wait. I'll reach out to the customers about the delay.","start":31.56,"end":35.1,"clipSrc":"../../audio-sentences/t5-44-meaning-07.mp3","clipSourceStart":31.48}]},"t5-47":{"conversationId":"t5-47","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[12,13]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-47-u01","speaker":"W","text":"Thanks for coming in, Marcos.","start":6,"end":7.65,"clipSrc":"../../audio-sentences/t5-47-s01.mp3","clipSourceStart":5.92},{"id":"t5-47-u02","speaker":"W","text":"I just got the results from the consulting firm we hired.","start":8.07,"end":11.28,"clipSrc":"../../audio-sentences/t5-47-s02.mp3","clipSourceStart":7.99},{"id":"t5-47-u03","speaker":"W","text":"They have some ideas about how we can increase sales of our denim blue jeans.","start":11.67,"end":16.17,"clipSrc":"../../audio-sentences/t5-47-s03.mp3","clipSourceStart":11.59},{"id":"t5-47-u04","speaker":"M","text":"I hope so. What does our target audience want?","start":16.56,"end":19.71,"clipSrc":"../../audio-sentences/t5-47-meaning-04.mp3","clipSourceStart":16.48},{"id":"t5-47-u05","speaker":"W","text":"Well, they think it's time we updated our brand with new styles or colors.","start":20.13,"end":25.29,"clipSrc":"../../audio-sentences/t5-47-s06.mp3","clipSourceStart":20.05},{"id":"t5-47-u06","speaker":"M","text":"You know, it takes a lot of effort to develop and launch new styles.","start":25.74,"end":29.91,"clipSrc":"../../audio-sentences/t5-47-s07.mp3","clipSourceStart":25.66},{"id":"t5-47-u07","speaker":"W","text":"Yes. But, if we don't do it, another company will.","start":30.39,"end":33.69,"clipSrc":"../../audio-sentences/t5-47-meaning-07.mp3","clipSourceStart":30.31},{"id":"t5-47-u08","speaker":"M","text":"You're right. I'll ask Junko to come up with some new designs for us to consider.","start":34.08,"end":38.85,"clipSrc":"../../audio-sentences/t5-47-meaning-08.mp3","clipSourceStart":34}]},"t5-50":{"conversationId":"t5-50","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[13,14]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-50-u01","speaker":"M","text":"Hi, Gabriela. Thanks for agreeing to give me the highlights of the budget discussion from the monthly meeting.","start":5.82,"end":11.4,"clipSrc":"../../audio-sentences/t5-50-meaning-01.mp3","clipSourceStart":5.74},{"id":"t5-50-u02","speaker":"M","text":"I'm back from vacation and still catching up.","start":11.76,"end":14.13,"clipSrc":"../../audio-sentences/t5-50-s03.mp3","clipSourceStart":11.68},{"id":"t5-50-u03","speaker":"W","text":"Sure. Here's a copy of the report.","start":14.46,"end":16.74,"clipSrc":"../../audio-sentences/t5-50-meaning-03.mp3","clipSourceStart":14.38},{"id":"t5-50-u04","speaker":"W","text":"Everyone on the board of Tennis United agreed to the fee increase for the tennis camp for young players.","start":17.04,"end":24.24,"clipSrc":"../../audio-sentences/t5-50-s06.mp3","clipSourceStart":16.96},{"id":"t5-50-u05","speaker":"M","text":"Good. And why do we have T-shirts listed as an expense item?","start":24.63,"end":28.77,"clipSrc":"../../audio-sentences/t5-50-meaning-05.mp3","clipSourceStart":24.55},{"id":"t5-50-u06","speaker":"W","text":"Although the next tournament's in the fall, the T-shirts were ordered very early.","start":29.28,"end":33.36,"clipSrc":"../../audio-sentences/t5-50-s09.mp3","clipSourceStart":29.2},{"id":"t5-50-u07","speaker":"W","text":"That way we received half off the price, since the supplier wanted to get rid of his summer inventory.","start":33.57,"end":39.18,"clipSrc":"../../audio-sentences/t5-50-s10.mp3","clipSourceStart":33.49}]},"t5-53":{"conversationId":"t5-53","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[14,15]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-53-u01","speaker":"W","text":"The first item on today's meeting agenda is our bid to renovate the Morrisville Bridge.","start":7.26,"end":12.78,"clipSrc":"../../audio-sentences/t5-53-s01.mp3","clipSourceStart":7.18},{"id":"t5-53-u02","speaker":"W","text":"Do we have an update on that yet?","start":13.26,"end":15.15,"clipSrc":"../../audio-sentences/t5-53-s02.mp3","clipSourceStart":13.18},{"id":"t5-53-u03","speaker":"M1","text":"Yes—unfortunately we didn't get the contract.","start":15.57,"end":19.29,"clipSrc":"../../audio-sentences/t5-53-s03.mp3","clipSourceStart":15.49},{"id":"t5-53-u04","speaker":"M2","text":"Yes, the only explanation given was that another construction company submitted a proposal with a shorter timeline.","start":19.68,"end":26.28,"clipSrc":"../../audio-sentences/t5-53-s04.mp3","clipSourceStart":19.6},{"id":"t5-53-u05","speaker":"W","text":"So, what do we know about this competitor? Have they worked on other local projects?","start":27.12,"end":32.43,"clipSrc":"../../audio-sentences/t5-53-s05.mp3","clipSourceStart":27.04},{"id":"t5-53-u06","speaker":"M1","text":"The only thing I heard was their name—CDQ Construction Company.","start":32.79,"end":37.62,"clipSrc":"../../audio-sentences/t5-53-s06.mp3","clipSourceStart":32.71},{"id":"t5-53-u07","speaker":"W","text":"Well, I'd like to know more about them.","start":37.95,"end":39.81,"clipSrc":"../../audio-sentences/t5-53-s07.mp3","clipSourceStart":37.87},{"id":"t5-53-u08","speaker":"W","text":"Can you two do some research before our next meeting?","start":40.29,"end":43.2,"clipSrc":"../../audio-sentences/t5-53-s08.mp3","clipSourceStart":40.21}]},"t5-56":{"conversationId":"t5-56","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[15,16]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-56-u01","speaker":"W","text":"Did you see that the results of last month's employee survey have been compiled? All the staff feedback is available.","start":5.88,"end":12.06,"clipSrc":"../../audio-sentences/t5-56-s01.mp3","clipSourceStart":5.8},{"id":"t5-56-u02","speaker":"M","text":"Yes, and I just finished reviewing the comments.","start":12.33,"end":15.72,"clipSrc":"../../audio-sentences/t5-56-s02.mp3","clipSourceStart":12.25},{"id":"t5-56-u03","speaker":"W","text":"You know, I noticed one recurring complaint.","start":16.02,"end":18.84,"clipSrc":"../../audio-sentences/t5-56-s03.mp3","clipSourceStart":15.94},{"id":"t5-56-u04","speaker":"W","text":"The size of the break room is too small.","start":19.23,"end":21.3,"clipSrc":"../../audio-sentences/t5-56-s04.mp3","clipSourceStart":19.15},{"id":"t5-56-u05","speaker":"W","text":"Perhaps we could enlarge the break room by having the wall taken down between it and the meeting room next door.","start":21.75,"end":27.18,"clipSrc":"../../audio-sentences/t5-56-s05.mp3","clipSourceStart":21.67},{"id":"t5-56-u06","speaker":"M","text":"Well, we do have money available in the budget.","start":27.51,"end":30.66,"clipSrc":"../../audio-sentences/t5-56-s06.mp3","clipSourceStart":27.43},{"id":"t5-56-u07","speaker":"W","text":"Then could you reach out to your contact at the construction company?","start":31.08,"end":34.38,"clipSrc":"../../audio-sentences/t5-56-s07.mp3","clipSourceStart":31},{"id":"t5-56-u08","speaker":"M","text":"I can't do it this afternoon, since I need to see a dentist, but I will definitely make the call.","start":34.74,"end":40.35,"clipSrc":"../../audio-sentences/t5-56-s08.mp3","clipSourceStart":34.66}]},"t5-59":{"conversationId":"t5-59","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[16,17]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-59-u01","speaker":"W","text":"Thanks for calling Hang's Metal Recycling Company.","start":5.97,"end":9.03,"clipSrc":"../../audio-sentences/t5-59-s01.mp3","clipSourceStart":5.89},{"id":"t5-59-u02","speaker":"W","text":"How can I help you?","start":9.09,"end":10.08,"clipSrc":"../../audio-sentences/t5-59-s02.mp3","clipSourceStart":9.03},{"id":"t5-59-u03","speaker":"M","text":"Hi. I'm with Shannak Construction Company. We've got a lot of brass metal scrap from a recent remodeling job.","start":10.53,"end":17.88,"clipSrc":"../../audio-sentences/t5-59-meaning-03.mp3","clipSourceStart":10.45},{"id":"t5-59-u04","speaker":"M","text":"Are you currently buying metal scrap?","start":18.36,"end":20.4,"clipSrc":"../../audio-sentences/t5-59-s06.mp3","clipSourceStart":18.28},{"id":"t5-59-u05","speaker":"W","text":"Yes, we are. We currently pay two dollars a pound.","start":20.85,"end":24.42,"clipSrc":"../../audio-sentences/t5-59-meaning-05.mp3","clipSourceStart":20.77},{"id":"t5-59-u06","speaker":"M","text":"Oh, there's another recycling center that pays two dollars and twenty-five cents a pound.","start":24.81,"end":29.55,"clipSrc":"../../audio-sentences/t5-59-s09.mp3","clipSourceStart":24.73},{"id":"t5-59-u07","speaker":"M","text":"Would you be willing to match their price?","start":30.06,"end":32.34,"clipSrc":"../../audio-sentences/t5-59-s10.mp3","clipSourceStart":29.98},{"id":"t5-59-u08","speaker":"W","text":"Yes, we have a price-match guarantee.","start":32.58,"end":35.31,"clipSrc":"../../audio-sentences/t5-59-s11.mp3","clipSourceStart":32.5},{"id":"t5-59-u09","speaker":"M","text":"Great. I'll bring the metal to you this afternoon, then.","start":35.64,"end":38.85,"clipSrc":"../../audio-sentences/t5-59-meaning-09.mp3","clipSourceStart":35.56}]},"t5-62":{"conversationId":"t5-62","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[17,18]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-62-u01","speaker":"W","text":"Hi, I just got off the phone with management.","start":7.53,"end":10.17,"clipSrc":"../../audio-sentences/t5-62-s01.mp3","clipSourceStart":7.45},{"id":"t5-62-u02","speaker":"W","text":"They're not happy. The construction of the train tunnel isn't progressing fast enough.","start":10.38,"end":15.27,"clipSrc":"../../audio-sentences/t5-62-meaning-02.mp3","clipSourceStart":10.3},{"id":"t5-62-u03","speaker":"M","text":"Yeah, I'm not surprised.","start":15.75,"end":17.49,"clipSrc":"../../audio-sentences/t5-62-s04.mp3","clipSourceStart":15.67},{"id":"t5-62-u04","speaker":"M","text":"The drilling is done now.","start":17.88,"end":19.26,"clipSrc":"../../audio-sentences/t5-62-s05.mp3","clipSourceStart":17.8},{"id":"t5-62-u05","speaker":"M","text":"The thing is, we can't start installing the support columns until we have all the materials for the concrete.","start":19.5,"end":24.84,"clipSrc":"../../audio-sentences/t5-62-s06.mp3","clipSourceStart":19.42},{"id":"t5-62-u06","speaker":"W","text":"When are the materials going to get here?","start":25.14,"end":26.64,"clipSrc":"../../audio-sentences/t5-62-s07.mp3","clipSourceStart":25.06},{"id":"t5-62-u07","speaker":"M","text":"A week, maybe two.","start":27.3,"end":28.8,"clipSrc":"../../audio-sentences/t5-62-s08.mp3","clipSourceStart":27.22},{"id":"t5-62-u08","speaker":"W","text":"Let's see if the shipment can be expedited.","start":29.04,"end":31.29,"clipSrc":"../../audio-sentences/t5-62-s09.mp3","clipSourceStart":28.96},{"id":"t5-62-u09","speaker":"W","text":"Can you do that?","start":31.74,"end":32.67,"clipSrc":"../../audio-sentences/t5-62-s10.mp3","clipSourceStart":31.66},{"id":"t5-62-u10","speaker":"M","text":"Sure. I'll call the supplier to ask about getting it here sooner.","start":33.15,"end":36.57,"clipSrc":"../../audio-sentences/t5-62-meaning-10.mp3","clipSourceStart":33.07},{"id":"t5-62-u11","speaker":"W","text":"In the meantime, I'm going to write an e-mail to management to explain how we're attempting to resolve the situation.","start":36.9,"end":42.66,"clipSrc":"../../audio-sentences/t5-62-s13.mp3","clipSourceStart":36.82}]},"t5-65":{"conversationId":"t5-65","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[19,20]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-65-u01","speaker":"M","text":"The city just posted its new parking rates, and we need to talk about how they'll affect our restaurant's food delivery service.","start":6.78,"end":13.95,"clipSrc":"../../audio-sentences/t5-65-s01.mp3","clipSourceStart":6.7},{"id":"t5-65-u02","speaker":"M","text":"I'm worried we'll lose money because we'll need to pay more for parking while the delivery driver takes the food to customers.","start":14.28,"end":21.09,"clipSrc":"../../audio-sentences/t5-65-s02.mp3","clipSourceStart":14.2},{"id":"t5-65-u03","speaker":"W","text":"Wow. Parking in our main delivery area is up to fifteen dollars an hour? That is a problem.","start":21.63,"end":29.46,"clipSrc":"../../audio-sentences/t5-65-meaning-03.mp3","clipSourceStart":21.55},{"id":"t5-65-u04","speaker":"W","text":"But offering free delivery attracts a lot of business.","start":29.82,"end":33.24,"clipSrc":"../../audio-sentences/t5-65-s05.mp3","clipSourceStart":29.74},{"id":"t5-65-u05","speaker":"W","text":"What else can we do to lower expenses?","start":33.51,"end":35.82,"clipSrc":"../../audio-sentences/t5-65-s06.mp3","clipSourceStart":33.43},{"id":"t5-65-u06","speaker":"M","text":"We could start using bicycle delivery whenever possible.","start":36.36,"end":39.72,"clipSrc":"../../audio-sentences/t5-65-s07.mp3","clipSourceStart":36.28},{"id":"t5-65-u07","speaker":"M","text":"That should help.","start":40.02,"end":40.98,"clipSrc":"../../audio-sentences/t5-65-s08.mp3","clipSourceStart":39.94},{"id":"t5-65-u08","speaker":"W","text":"Good idea. I'll talk to our drivers to see who's willing to switch to bicycle deliveries for customers nearby.","start":41.34,"end":48.54,"clipSrc":"../../audio-sentences/t5-65-meaning-08.mp3","clipSourceStart":41.26},{"id":"t5-65-u09","speaker":"W","text":"Some people really like the exercise.","start":48.87,"end":50.94,"clipSrc":"../../audio-sentences/t5-65-s11.mp3","clipSourceStart":48.79}]},"t5-68":{"conversationId":"t5-68","source":{"file":"C:\\Users\\Nam\\Documents\\Transcript Part 2\\Transcript test 5 ets 2026.pdf","pages":[20,21]},"timebase":"source-seconds","timingMethod":"Scene starts reuse existing measured source sentence starts; grouping follows original speaker turns and complete sentences.","utterances":[{"id":"t5-68-u01","speaker":"M","text":"When customers walk into Southern Regional Bank, I want them to feel confident about entrusting their money to us.","start":6.69,"end":13.14,"clipSrc":"../../audio-sentences/t5-68-s01.mp3","clipSourceStart":6.61},{"id":"t5-68-u02","speaker":"M","text":"As I mentioned the last time we met, I'm hoping your interior design firm can give our lobby a more polished, professional look.","start":13.68,"end":21.09,"clipSrc":"../../audio-sentences/t5-68-s02.mp3","clipSourceStart":13.6},{"id":"t5-68-u03","speaker":"W","text":"Our proposal does just that.","start":21.51,"end":23.37,"clipSrc":"../../audio-sentences/t5-68-s03.mp3","clipSourceStart":21.43},{"id":"t5-68-u04","speaker":"W","text":"Here—take a look.","start":23.73,"end":24.78,"clipSrc":"../../audio-sentences/t5-68-s04.mp3","clipSourceStart":23.65},{"id":"t5-68-u05","speaker":"W","text":"The cover page includes a summary of the renovations.","start":25.29,"end":28.17,"clipSrc":"../../audio-sentences/t5-68-s05.mp3","clipSourceStart":25.21},{"id":"t5-68-u06","speaker":"W","text":"Hmm. Do you really think we need skylights? That would be a big expense.","start":28.8,"end":33.84,"clipSrc":"../../audio-sentences/t5-68-meaning-06.mp3","clipSourceStart":28.72},{"id":"t5-68-u07","speaker":"W","text":"There aren't many windows in your lobby, so it's the best way to bring more natural light into the room.","start":34.56,"end":39.72,"clipSrc":"../../audio-sentences/t5-68-s08.mp3","clipSourceStart":34.48},{"id":"t5-68-u08","speaker":"W","text":"Besides, our proposed renovations would actually come in under budget.","start":40.2,"end":44.1,"clipSrc":"../../audio-sentences/t5-68-s09.mp3","clipSourceStart":40.12},{"id":"t5-68-u09","speaker":"W","text":"If you turn to page four, you'll see the cost breakdown.","start":44.58,"end":47.58,"clipSrc":"../../audio-sentences/t5-68-s10.mp3","clipSourceStart":44.5}]}};
